# Clone a template object before modifying

**Class:** Array | **Method:** clone

> When creating multiple parameter descriptors from a template, clone() produces an independent deep copy. Without it, all entries would share the same object reference and the last modification would overwrite all previous ones.

```javascript
// Context: When creating multiple parameter descriptors from a
// template, clone() produces an independent deep copy. Without
// it, all entries would share the same object reference and
// the last modification would overwrite all previous ones.

const var template = {
    "ID": "",
    "min": -100.0,
    "max": 0.0,
    "mode": "Decibel",
    "defaultValue": -100.0,
    "connections": [{ "processorId": "", "parameterId": "Gain" }]
};

const var params = [];

// Each clone is independent -- modifying one doesn't affect others
for(i = 0; i < 4; i++)
{
    var p = template.clone();
    var name = "Send " + (i + 1);
    p.ID = name;
    p.connections[0].processorId = name;
    params.push(p);
}

Console.print(params[0].ID);  // "Send 1"
Console.print(params[3].ID);  // "Send 4"
```

# Build a master automation list from per-channel sub-arrays

**Class:** Array | **Method:** concat

> A plugin with multiple channel strips builds its full automation parameter list by creating sub-arrays per channel, then concatenating them into one master array. concat() modifies in-place -- there is no return value.

```javascript
// Context: A plugin with multiple channel strips builds its full
// automation parameter list by creating sub-arrays per channel,
// then concatenating them into one master array. concat() modifies
// in-place -- there is no return value.

inline function makeChannelParams(channelIndex)
{
    local params = [];
    local ch = channelIndex + 1;

    params.push({
        "ID": "Volume " + ch,
        "min": -100.0,
        "max": 0.0,
        "connections": [{ "processorId": "Gain " + ch, "parameterId": "Gain" }]
    });

    params.push({
        "ID": "Pan " + ch,
        "min": -100.0,
        "max": 100.0,
        "connections": [{ "processorId": "Gain " + ch, "parameterId": "Balance" }]
    });

    return params;
}

// Accumulate all channel parameters into one list
const var NUM_CHANNELS = 4;
const var allParams = [];

for(i = 0; i < NUM_CHANNELS; i++)
    allParams.concat(makeChannelParams(i));

Console.print(allParams.length); // 8 (2 params x 4 channels)
```

