# Loading an IR file from a selection list

**Class:** AudioSampleProcessor | **Method:** setFile

> Convolution reverb plugins populate a ComboBox with IR names and load the selected file using a pool reference string with {SAMPLE_FOLDER}.

```javascript
// Context: Convolution reverb plugins populate a ComboBox with IR names and load
// the selected file using a pool reference string with {SAMPLE_FOLDER}.

const var reverb = Synth.getAudioSampleProcessor("ConvolutionReverb1");

// Build a list of IR files from the Samples/IR subfolder
const var irFolder = FileSystem.getFolder(FileSystem.Samples).getChildFile("IR");
const var irFiles = FileSystem.findFiles(irFolder, "*.wav", false);

const var irSelector = Content.getComponent("IRSelector");
irSelector.set("items", "");

for (f in irFiles)
    irSelector.addItem(f.toString(1));

inline function onIRSelected(component, value)
{
    if (value > 0)
    {
        local file = irFiles[value - 1];
        reverb.setFile(file.toString(0));
    }
}

irSelector.setControlCallback(onIRSelected);
```

# File scanning with progress and thread-safe UI updates

**Class:** BackgroundTask | **Method:** callOnBackgroundThread

> A shared BackgroundTask scans a directory tree on a background thread, reporting progress via the loading overlay. The .lock(Threads.Scripting) block ensures thread-safe access to scripting APIs from the background thread.

```javascript
// Context: A shared BackgroundTask scans a directory tree on a background thread,
// reporting progress via the loading overlay. The .lock(Threads.Scripting) block
// ensures thread-safe access to scripting APIs from the background thread.

const var fileScanner = Engine.createBackgroundTask("FileScanner");
fileScanner.setForwardStatusToLoadingThread(true);
fileScanner.setTimeOut(4000);

inline function scanFiles(task)
{
    local root = FileSystem.getFolder(FileSystem.Samples);
    local allFiles = FileSystem.findFiles(root, "*.wav", true);

    for (i = 0; i < allFiles.length; i++)
    {
        if (task.shouldAbort())
            return;

        task.setProgress(i / allFiles.length);
        task.setStatusMessage("Scanning: " + allFiles[i].toString(1));

        {
            .lock(Threads.Scripting);

            // Thread-safe operations that touch the scripting engine
            task.setProperty("lastFile", allFiles[i].toString(1));
            task.setProperty("fileCount", i + 1);
        }
    }
};

// Multiple UI actions can trigger the same task -- the previous scan
// is automatically stopped before the new one starts.
fileScanner.callOnBackgroundThread(scanFiles);
```

# Mode switching that reconfigures multiple processors

**Class:** BackgroundTask | **Method:** killVoicesAndCall

> A multi-mode instrument switches between performance modes by changing bypass states, mic routing, and effect settings across many processors. killVoicesAndCall suspends audio output during reconfiguration, preventing glitches from mid-stream state changes.

```javascript
// Context: A multi-mode instrument switches between performance modes by
// changing bypass states, mic routing, and effect settings across many
// processors. killVoicesAndCall suspends audio output during reconfiguration,
// preventing glitches from mid-stream state changes.

const var modeTask = Engine.createBackgroundTask("ModeSwitch");

const var NUM_MODES = 3;
reg currentMode = -1;

const var reverbSend = Synth.getChildSynth("ReverbSend");
const var effectChain = Synth.getEffect("MainFX");

inline function applyMode()
{
    // Runs on the sample loading thread with all voices killed.
    // Safe to change bypass states, attributes, and routing here.
    reverbSend.setBypassed(currentMode == 1);
    effectChain.setBypassed(currentMode == 0);
};

inline function setMode(component, value)
{
    if (!value)
        return;

    local newMode = parseInt(component.get("text"));

    if (currentMode != newMode)
    {
        currentMode = newMode;
        modeTask.killVoicesAndCall(applyMode);
    }
};
```

# Abort-then-restart pattern for shared background tasks

**Class:** BackgroundTask | **Method:** sendAbortSignal

> When multiple UI actions share a single BackgroundTask (e.g. a file scanner), explicitly abort the current operation before starting a new one. This avoids the implicit blocking that callOnBackgroundThread performs when a task is already running.

```javascript
// Context: When multiple UI actions share a single BackgroundTask (e.g. a file
// scanner), explicitly abort the current operation before starting a new one.
// This avoids the implicit blocking that callOnBackgroundThread performs when
// a task is already running.

const var scanner = Engine.createBackgroundTask("Scanner");
scanner.setTimeOut(4000);

inline function scanFolder(task)
{
    local files = FileSystem.findFiles(
        FileSystem.getFolder(FileSystem.Samples), "*.wav", true
    );

    for (i = 0; i < files.length; i++)
    {
        if (task.shouldAbort())
            return;

        task.setProgress(i / files.length);
    }
};

inline function startScan()
{
    // Explicitly abort any running scan before starting a new one
    scanner.sendAbortSignal(true);
    scanner.callOnBackgroundThread(scanFolder);
};
```

# Finish callback showing start/complete/cancel states

**Class:** BackgroundTask | **Method:** setFinishCallback

```javascript
