# Restore sparse lane state with one reusable scratch buffer

**Class:** Buffer | **Method:** fromBase64

> Import routines decode many payloads, so they reuse one temp Buffer and handle "EMPTY" entries explicitly.

```javascript
// Context: Import routines decode many payloads, so they reuse one temp Buffer and handle "EMPTY" entries explicitly.

const var NUM_STEPS = 16;

const var source = Buffer.create(NUM_STEPS);
source[2] = 1.0;

const var encodedLanes = ["EMPTY", source.toBase64(), "EMPTY"];
const var decodedLanes = [];
const var scratch = Buffer.create(NUM_STEPS);

for (entry in encodedLanes)
{
    if (entry == "EMPTY")
    {
        decodedLanes.push(Buffer.create(NUM_STEPS));
        continue;
    }

    local ok = scratch.fromBase64(entry);

    if (!ok)
    {
        decodedLanes.push(Buffer.create(NUM_STEPS));
        continue;
    }

    local lane = Buffer.create(NUM_STEPS);
    scratch >> lane;
    decodedLanes.push(lane);
}
```

# Find the last active block before exporting audio

**Class:** Buffer | **Method:** getMagnitude

> Export code scans fixed windows to remove trailing silence while keeping release tails.

```javascript
// Context: Export code scans fixed windows to remove trailing silence while keeping release tails.

const var TOTAL_SAMPLES = 4096;
const var ANALYSIS_BLOCK_SIZE = 256;
const var SILENCE_THRESHOLD = 0.00001;

const var left = Buffer.create(TOTAL_SAMPLES);
const var right = Buffer.create(TOTAL_SAMPLES);

left[2200] = 0.4;
right[2201] = -0.3;

local lastActiveSample = 0;

for (i = 0; i < TOTAL_SAMPLES - ANALYSIS_BLOCK_SIZE; i += ANALYSIS_BLOCK_SIZE)
{
    local l = left.getMagnitude(i, ANALYSIS_BLOCK_SIZE);
    local r = right.getMagnitude(i, ANALYSIS_BLOCK_SIZE);
    local g = Math.max(l, r);

    if (g > SILENCE_THRESHOLD)
        lastActiveSample = i + ANALYSIS_BLOCK_SIZE;
}

Console.print(lastActiveSample); // 2304
```

