# Clearing a specific modulation chain before rebuilding

**Class:** Builder | **Method:** clearChildren

> When rebuilding only part of the module tree (e.g. the gain modulators of an oscillator group), use clearChildren() to remove existing children from a specific chain without affecting the rest.

```javascript
// Context: When rebuilding only part of the module tree (e.g. the gain
// modulators of an oscillator group), use clearChildren() to remove
// existing children from a specific chain without affecting the rest.

const var b = Synth.createBuilder();

inline function buildOscillator(index)
{
    local group = b.create(b.SoundGenerators.SynthGroup,
        "OSC" + index, 0, b.ChainIndexes.Direct);

    // Clear existing gain modulators before adding new ones
    b.clearChildren(group, b.ChainIndexes.Gain);

    local synth = b.create(b.SoundGenerators.WavetableSynth,
        "WT" + index, group, b.ChainIndexes.Direct);

    // Add MatrixModulators to the now-empty gain chain
    b.create(b.Modulators.MatrixModulator,
        "OSC" + index + " Gain", group, b.ChainIndexes.Gain);
    b.create(b.Modulators.MatrixModulator,
        "OSC" + index + " Pan", group, b.ChainIndexes.Gain);
}

b.clear();
buildOscillator(1);
b.flush();

Console.print(Synth.getChildSynth("OSC1").getId());
Console.print(Synth.getModulator("OSC1 Gain").getId());
```

# Per-channel external script linking in a loop

**Class:** Builder | **Method:** connectToScript

> When building N channels that each need a MIDI script processor (e.g. for arpeggio, loop control, or note processing), create a ScriptProcessor for each channel and connect it to a shared .js file. Each instance gets its own state but shares the same script logic.

```javascript
// Context: When building N channels that each need a MIDI script processor
// (e.g. for arpeggio, loop control, or note processing), create a
// ScriptProcessor for each channel and connect it to a shared .js file.
// Each instance gets its own state but shares the same script logic.

const var NUM_CHANNELS = 4;
const var b = Synth.createBuilder();
b.clear();

for (i = 0; i < NUM_CHANNELS; i++)
{
    var container = b.create(b.SoundGenerators.SynthChain,
        "Container " + (i + 1), 0, b.ChainIndexes.Direct);
    var synth = b.create(b.SoundGenerators.SilentSynth,
        "Channel " + (i + 1), container, b.ChainIndexes.Direct);

    // Create a ScriptProcessor and connect it to the shared script
    var scriptProc = b.create(b.MidiProcessors.ScriptProcessor,
        "MidiScript " + (i + 1), synth, b.ChainIndexes.Midi);

    b.connectToScript(scriptProc,
        "{PROJECT_FOLDER}ConnectedScripts/ChannelProcessor.js");
}

b.flush();
```

