# Feeding stack properties to a shader as uniform arrays

**Class:** FixObjectStack | **Method:** copy

> A visualization system copies per-event property columns from the stack into Buffers, then passes them as shader uniform data. copy() reads all allocated slots (including unused ones with default values), which works here because the shader uses the stack size to know how many entries are valid.

```javascript
// Context: A visualization system copies per-event property columns from
// the stack into Buffers, then passes them as shader uniform data.
// copy() reads all allocated slots (including unused ones with default
// values), which works here because the shader uses the stack size to
// know how many entries are valid.

const var f = Engine.createFixObjectFactory({
    "start": -1.0,
    "end": -1.0,
    "key": 0,
    "velocity": 0
});

const var NUM_SLOTS = 128;
const var stack = f.createStack(NUM_SLOTS);

// Preallocate Buffers matching the stack capacity
const var startBuffer = Buffer.create(NUM_SLOTS);
const var endBuffer = Buffer.create(NUM_SLOTS);
const var keyBuffer = Buffer.create(NUM_SLOTS);

const var shader = Content.createShader("visualizer.glsl");

// In a timer callback: copy columns and update shader
inline function updateShaderData()
{
    stack.copy("start", startBuffer);
    stack.copy("end", endBuffer);
    stack.copy("key", keyBuffer);

    shader.setUniformData("start", startBuffer);
    shader.setUniformData("end", endBuffer);
    shader.setUniformData("key", keyBuffer);

    // Tell the shader how many entries are valid
    shader.setUniform("numActive", stack.size());
}
```

# Reusable temp object pattern for event tracking

**Class:** FixObjectStack | **Method:** insert

> Real-time note tracking uses a single temp object to avoid per-event allocation. Mutate properties, then insert() copies the data.

```javascript
// Context: Real-time note tracking uses a single temp object to avoid
// per-event allocation. Mutate properties, then insert() copies the data.

const var f = Engine.createFixObjectFactory({
    "eventId": -1,
    "start": -1.0,
    "end": -1.0,
    "key": 0,
    "velocity": 0,
    "active": false
});

inline function compareById(a, b)
{
    local id1 = a.eventId;
    local id2 = b.eventId;
    if (id2 < id1) return -1;
    if (id2 > id1) return 1;
    return 0;
}

f.setCompareFunction(compareById);
const var stack = f.createStack(128);
const var temp = f.create();

// Reuse temp for each note-on -- insert() copies data into the stack
inline function onNoteOn(eventId, noteNumber, vel)
{
    // Manual capacity management: evict oldest entry when near full
    if (stack.size() >= 127)
    {
        local oldestIdx = 0;
        local oldestStart = 0.0;

        for (i = 0; i < stack.size(); i++)
        {
            if (stack[i].start > oldestStart)
            {
                oldestIdx = i;
                oldestStart = stack[i].start;
            }
        }

        stack.removeElement(oldestIdx);
    }

    temp.eventId = eventId;
    temp.key = noteNumber;
    temp.velocity = vel;
    temp.start = 0.0;
    temp.end = -1.0;
    temp.active = true;
    stack.insert(temp);
}

// Demonstrate the pattern
onNoteOn(100, 60, 80);
onNoteOn(101, 64, 100);
onNoteOn(102, 67, 90);

Console.print(stack.size()); // 3
```

# Safe removal during index-based iteration

**Class:** FixObjectStack | **Method:** removeElement

> Because removeElement() uses swap-and-pop, the loop index must be decremented after each removal to avoid skipping the swapped-in element.

```javascript
// Context: Because removeElement() uses swap-and-pop, the loop index
// must be decremented after each removal to avoid skipping the
// swapped-in element.

const var f = Engine.createFixObjectFactory({
    "eventId": -1,
    "start": 0.0,
    "end": -1.0,
    "active": false
});

const var stack = f.createStack(32);
const var obj = f.create();

// Populate with test data
obj.eventId = 1; obj.end = 0.5; stack.insert(obj);
obj.eventId = 2; obj.end = 2.0; stack.insert(obj);  // expired
obj.eventId = 3; obj.end = 0.3; stack.insert(obj);
obj.eventId = 4; obj.end = 1.5; stack.insert(obj);  // expired

inline function removeExpired()
{
    for (i = 0; i < stack.size(); i++)
    {
        if (stack[i].end > 1.0)
            stack.removeElement(i--);
        //                       ^^ critical: the last element was swapped
        //                          into slot i, so re-check this index
    }
}

removeExpired();
Console.print(stack.size()); // 2
```

