```javascript
// Context: An instrument exposes a fixed set of CC-controllable parameters.
// The popup should only show relevant CC numbers with descriptive labels
// instead of the default full list of 128 CCs.

const var mah = Engine.createMidiAutomationHandler();

// Define the CC numbers available for automation
const var NUM_SLOTS = 4;
const var CC_START = 20;
const var ccNumbers = [];
const var names = [];

for (i = 0; i < NUM_SLOTS; i++)
{
    ccNumbers.push(CC_START + i);
    names.push("Slot " + (i + 1));
}

// One CC per parameter - grays out already-assigned CCs in the popup
mah.setExclusiveMode(true);

// Only these CC numbers appear in the right-click automation popup
mah.setControllerNumbersInPopup(ccNumbers);

// Set the popup section header and per-CC display names.
// The nameArray is indexed by CC number, so populate the correct indices.
var nameArray = [];
for (i = 0; i < NUM_SLOTS; i++)
    nameArray[CC_START + i] = names[i];

mah.setControllerNumberNames("Automation", nameArray);
```

# Deduplication during sustain pedal release

**Class:** MidiList | **Method:** clear

> When the sustain pedal lifts, all sustained notes need release samples - but each note should only trigger once. Clear the list first, then use it as a "seen set" while processing the held notes.

```javascript
// Context: When the sustain pedal lifts, all sustained notes need release
// samples - but each note should only trigger once. Clear the list first,
// then use it as a "seen set" while processing the held notes.

const var processed = Engine.createMidiList();
const var heldNotes = Engine.createUnorderedStack();
heldNotes.setIsEventStack(true, heldNotes.EventId);

const var holder = Engine.createMessageHolder();

// When pedal releases, process each held note exactly once
inline function onPedalRelease()
{
    processed.clear();

    while (!heldNotes.isEmpty())
    {
        heldNotes.storeEvent(0, holder);
        heldNotes.removeElement(0);

        // Skip if this note number was already processed
        if (processed.getValue(holder.getNoteNumber()) != -1)
            continue;

        processed.setValue(holder.getNoteNumber(), 1);
        Synth.addMessageFromHolder(holder);
    }
}
```

