# Programmatically building a step sequence from slider data

**Class:** MidiPlayer | **Method:** flushMessageList

> Convert a velocity array (from a SliderPack or UI data) into MIDI note-on/note-off pairs and flush them into the current sequence

```javascript
// Context: Convert a velocity array (from a SliderPack or UI data) into
// MIDI note-on/note-off pairs and flush them into the current sequence

const var mp = Synth.getMidiPlayer("MidiPlayer1");
mp.setUseTimestampInTicks(true);
mp.create(4, 4, 1);

const var NOTE_NUMBER = 64;
const var NUM_STEPS = 16;
const var STEP_SIZE = mp.getTicksPerQuarter() / 4; // 16th note = 240 ticks

// Example velocity values (0.0 = silent, >0 = active)
const var velocities = [1.0, 0.0, 0.5, 0.0, 1.0, 0.0, 0.75, 0.0,
                        1.0, 0.0, 0.5, 0.0, 1.0, 0.0, 0.75, 0.0];

var noteList = [];
noteList.reserve(NUM_STEPS * 2);

for (i = 0; i < NUM_STEPS; i++)
{
    if (velocities[i] > 0.0)
    {
        var on = Engine.createMessageHolder();
        var off = Engine.createMessageHolder();

        on.setType(on.NoteOn);
        off.setType(on.NoteOff);

        on.setChannel(1);
        off.setChannel(1);

        on.setNoteNumber(NOTE_NUMBER);
        off.setNoteNumber(NOTE_NUMBER);

        on.setVelocity(parseInt(velocities[i] * 127));

        on.setTimestamp(i * STEP_SIZE);
        off.setTimestamp(i * STEP_SIZE + STEP_SIZE - 1);

        noteList.push(on);
        noteList.push(off);
    }
}

mp.flushMessageList(noteList);
```

# Writing note data to a specific pattern bank

**Class:** MidiPlayer | **Method:** flushMessageListToSequence

> In a multi-pattern sequencer, write programmatically generated notes to a specific pattern index. This avoids switching the active sequence just to write data.

```javascript
// Context: In a multi-pattern sequencer, write programmatically generated
// notes to a specific pattern index. This avoids switching the active
// sequence just to write data.

const var mp = Synth.getMidiPlayer("MidiPlayer1");
mp.setUseTimestampInTicks(true);
mp.clearAllSequences();
mp.create(4, 4, 1);
mp.create(4, 4, 1);

const var STEP_SIZE = mp.getTicksPerQuarter() / 4; // 16th note grid

inline function writePatternData(patternIndex, noteNumber, velocityArray)
{
    local notes = [];
    notes.reserve(velocityArray.length * 2);

    for (i = 0; i < velocityArray.length; i++)
    {
        if (velocityArray[i] == 0.0)
            continue;

        local on = Engine.createMessageHolder();
        local off = Engine.createMessageHolder();

        on.setType(on.NoteOn);
        off.setType(on.NoteOff);
        on.setChannel(1);
        off.setChannel(1);
        on.setNoteNumber(noteNumber);
        off.setNoteNumber(noteNumber);
        on.setVelocity(parseInt(velocityArray[i] * 127));
        on.setTimestamp(i * STEP_SIZE);
        off.setTimestamp(i * STEP_SIZE + STEP_SIZE - 1);

        notes.push(on);
        notes.push(off);
    }

    // Write to one-based pattern index without changing the active sequence
    mp.flushMessageListToSequence(notes, patternIndex + 1);
}

// Write to pattern 2 (internal index 1 -> one-based = 2)
writePatternData(1, 60, [1.0, 0.0, 0.5, 0.0]);
```

