# Setting up tick mode for musical editing

**Class:** MidiPlayer | **Method:** setUseTimestampInTicks

> Always enable tick mode early in initialization when building a step sequencer. Tick timestamps align to musical grid positions regardless of tempo changes.

```javascript
// Context: Always enable tick mode early in initialization when building
// a step sequencer. Tick timestamps align to musical grid positions
// regardless of tempo changes.

const var mp = Synth.getMidiPlayer("MidiPlayer1");

// Enable tick mode before any getEventList/flushMessageList calls
mp.setUseTimestampInTicks(true);
mp.create(4, 4, 1);

// Now timestamps are in MIDI ticks (960 per quarter note)
var tpq = mp.getTicksPerQuarter(); // Always 960

// Common grid divisions in ticks:
// Whole note    = tpq * 4 = 3840
// Half note     = tpq * 2 = 1920
// Quarter note  = tpq     = 960
// 8th note      = tpq / 2 = 480
// 16th note     = tpq / 4 = 240
// 32nd note     = tpq / 8 = 120
// Triplet 8th   = tpq / 3 = 320

// Create a note at the second 16th note position
var noteList = [];
var on = Engine.createMessageHolder();
var off = Engine.createMessageHolder();
on.setType(on.NoteOn);
off.setType(on.NoteOff);
on.setNoteNumber(64);
off.setNoteNumber(64);
on.setVelocity(100);
on.setChannel(1);
off.setChannel(1);
on.setTimestamp(240); // second 16th note
off.setTimestamp(480);
noteList.push(on);
noteList.push(off);
mp.flushMessageList(noteList);

var events = mp.getEventList();

for (e in events)
{
    if (e.isNoteOn())
    {
        // Timestamp is now in ticks, e.g. 240 = second 16th note
        var stepIndex = parseInt(e.getTimestamp() / (tpq / 4));
        Console.print("Step " + stepIndex);
    }
}
```

# Casting a MidiProcessor to MidiPlayer for playback control

**Class:** MidiProcessor | **Method:** asMidiPlayer

> When you obtain a generic MidiProcessor handle (e.g. from a loop over all MIDI processors), cast it to MidiPlayer to access playback methods. The reverse cast (MidiPlayer.asMidiProcessor()) is used for state serialization.

```javascript
// Context: When you obtain a generic MidiProcessor handle (e.g. from a loop
// over all MIDI processors), cast it to MidiPlayer to access playback methods.
// The reverse cast (MidiPlayer.asMidiProcessor()) is used for state serialization.

const var mp = Synth.getMidiProcessor("MIDIPlayer1");

// Cast to MidiPlayer -- throws if the module is not a MidiPlayer
const var player = mp.asMidiPlayer();

// Now you can use MidiPlayer-specific methods
player.setPlaybackPosition(0.0);
player.play(0);

// The reverse: cast MidiPlayer back to MidiProcessor for exportState()
const var player2 = Synth.getMidiPlayer("MIDIPlayer2");
const var mp2 = player2.asMidiProcessor();
var savedState = mp2.exportState();
```

# Factory preset system -- saving script processor UI state

**Class:** MidiProcessor | **Method:** exportScriptControls

> A custom preset system saves the UI control values of each script processor separately from modulators and effects. exportScriptControls() captures only knob/slider/button values without the script code itself, and restoreScriptControls() restores them without triggering recompilation.

```javascript
// Context: A custom preset system saves the UI control values of each script
// processor separately from modulators and effects. exportScriptControls()
// captures only knob/slider/button values without the script code itself,
// and restoreScriptControls() restores them without triggering recompilation.

const var midiProcessorIds = Synth.getIdList("MidiProcessor");
const var presetData = {"midiProcessors": {}};

inline function savePresetData()
{
    for (id in midiProcessorIds)
    {
        local mp = Synth.getMidiProcessor(id);

        // exportScriptControls only works on script processors --
        // built-in modules like Transposer or Arpeggiator will throw an error.
        // Use exportState() for those instead.
        presetData.midiProcessors[id] = mp.exportScriptControls();
    }
}

inline function loadPresetData()
{
    for (id in midiProcessorIds)
    {
        local mp = Synth.getMidiProcessor(id);

        if (typeof presetData.midiProcessors[id] == void)
            continue;

        // Restores UI control values without recompiling the script
        mp.restoreScriptControls(presetData.midiProcessors[id]);
    }
}
```

# Effect locking -- preserve processor state across preset changes

**Class:** MidiProcessor | **Method:** exportState

> A preset system that allows users to "lock" certain effects so they persist when loading a new preset. The state is captured as base64 before the preset loads and restored after.

```javascript
// Context: A preset system that allows users to "lock" certain effects so
// they persist when loading a new preset. The state is captured as base64
// before the preset loads and restored after.

const var NUM_FX_SLOTS = 3;
const var fxModules = [];
const var fxLockStates = [];
const var fxSavedStates = [];

for (i = 0; i < NUM_FX_SLOTS; i++)
{
    fxModules.push(Synth.getEffect("FX" + (i + 1)));
    fxLockStates.push(false);
    fxSavedStates.push("");
}

// Call before loading a new preset
inline function captureLockedStates()
{
    for (i = 0; i < NUM_FX_SLOTS; i++)
    {
        // Only capture state for locked slots
        fxSavedStates[i] = fxLockStates[i] ? fxModules[i].exportState() : "";
    }
}

// Call after loading a new preset
inline function restoreLockedStates()
{
    for (i = 0; i < NUM_FX_SLOTS; i++)
    {
        if (fxSavedStates[i].length > 0)
        {
            Console.print("Restoring locked state for " + fxModules[i].getId());
            fxModules[i].restoreState(fxSavedStates[i]);
        }
    }
}
```

