# Tooltip speech bubble with rounded corners

**Class:** Path | **Method:** quadraticTo

> quadraticTo creates smooth rounded corners on custom shapes that addRoundedRectangle cannot express - like a speech bubble with an arrow pointer on one side.

```javascript
// Context: quadraticTo creates smooth rounded corners on custom
// shapes that addRoundedRectangle cannot express - like a speech
// bubble with an arrow pointer on one side.

const var SHADOW = 10;
const var CORNER = 3;

inline function createBubblePath(width, height)
{
    local p = Content.createPath();
    local r = width - SHADOW;

    // Top edge with rounded corners
    p.startNewSubPath(SHADOW + CORNER, SHADOW);
    p.lineTo(r - CORNER, SHADOW);
    p.quadraticTo(r, SHADOW, r, SHADOW + CORNER);

    // Right edge with arrow pointer
    p.lineTo(r, 20);
    p.lineTo(r + 10, 30);
    p.lineTo(r, 40);
    p.lineTo(r, height - SHADOW - CORNER);

    // Bottom-right corner
    p.quadraticTo(r, height - SHADOW,
                  r - CORNER, height - SHADOW);

    // Bottom edge
    p.lineTo(SHADOW + CORNER, height - SHADOW);

    // Bottom-left corner
    p.quadraticTo(SHADOW, height - SHADOW,
                  SHADOW, height - CORNER - SHADOW);

    // Left edge back to start
    p.lineTo(SHADOW, SHADOW + CORNER);
    p.quadraticTo(SHADOW, SHADOW,
                  SHADOW + CORNER, SHADOW);

    p.closeSubPath();
    return p;
}

const var bubble = createBubblePath(200, 100);
```

# Envelope curve segment with adjustable curvature

**Class:** Path | **Method:** quadraticTo

> AHDSR envelope editors use quadraticTo to draw curved attack, decay, and release segments. The control point position is interpolated between start and end based on a curve parameter (0.0 = linear, approaching 1.0 = exponential).

```javascript
// Context: AHDSR envelope editors use quadraticTo to draw curved
// attack, decay, and release segments. The control point position
// is interpolated between start and end based on a curve parameter
// (0.0 = linear, approaching 1.0 = exponential).

const var p = Content.createPath();
var x = 0.0;
var y = 1.0;  // start at bottom
var cx = 0.0;
var cy = 1.0;

p.startNewSubPath(x, y);

// Attack segment with curve factor
var attackTime = 0.3;
var attackLevel = 0.0;  // 0.0 = top
var curveFactor = 0.5;  // 0 = linear, 1 = extreme curve

x = attackTime;
y = attackLevel;

// Interpolate control point between start and end
cy = curveFactor * cy + (1.0 - curveFactor) * y;
cx = (1.0 - curveFactor) * cx + curveFactor * x;

p.quadraticTo(cx, cy, x, y);
```

# Scaling an envelope path from normalized to pixel coordinates

**Class:** Path | **Method:** scaleToFit

> Envelope editors build paths in normalized [0, 1] space (where x = time proportion, y = level) then use scaleToFit to map them into the actual panel dimensions. The false parameter for preserveProportions allows the path to stretch to fill the full width and height independently.

```javascript
// Context: Envelope editors build paths in normalized [0, 1] space
// (where x = time proportion, y = level) then use scaleToFit to map
// them into the actual panel dimensions. The false parameter for
// preserveProportions allows the path to stretch to fill the full
// width and height independently.

const var MARGIN = 5;
const var path = Content.createPath();

// Build envelope in normalized coordinates
path.startNewSubPath(1.0, 0.0);  // anchor top-right
path.startNewSubPath(0.0, 1.0);  // start at bottom-left

// Attack
path.quadraticTo(0.1, 0.2, 0.2, 0.0);
// Hold
path.lineTo(0.3, 0.0);
// Decay
path.quadraticTo(0.4, 0.3, 0.5, 0.4);
// Sustain
path.lineTo(0.7, 0.4);
// Release
path.quadraticTo(0.85, 0.7, 1.0, 1.0);

var boundsBeforeScale = path.getBounds(1.0);

// Scale to target dimensions with margin
const var targetWidth = 300;
const var targetHeight = 150;
path.scaleToFit(MARGIN, MARGIN, targetWidth - 2 * MARGIN,
                targetHeight - 2 * MARGIN, false);

var boundsAfterScale = path.getBounds(1.0);
```

# Bounds anchoring pattern for normalized-space paths

**Class:** Path | **Method:** startNewSubPath

> The most frequent use of startNewSubPath is NOT to begin visible drawing, but to anchor the path's bounding box to a known coordinate range. When a path will be rendered via g.drawPath(path, targetArea), the path is scaled from its bounding box to the target area. Without anchoring, an arc or partial shape has a bounding box that only covers its actual geometry, causing misalignment when scaled.

```javascript
// Context: The most frequent use of startNewSubPath is NOT to begin
// visible drawing, but to anchor the path's bounding box to a known
// coordinate range. When a path will be rendered via
// g.drawPath(path, targetArea), the path is scaled from its bounding
// box to the target area. Without anchoring, an arc or partial shape
// has a bounding box that only covers its actual geometry, causing
// misalignment when scaled.

var p = Content.createPath();

// Anchor to unit square - these points are invisible but define bounds
p.startNewSubPath(0.0, 0.0);
p.startNewSubPath(1.0, 1.0);

// Now add actual geometry
p.addArc([0.0, 0.0, 1.0, 1.0], -2.4, 2.4);

// The path's bounds are [0, 0, 1, 1] regardless of the arc extent
var bounds = p.getBounds(1.0);
```

