# Multi-sampler mic position management with mode matrix

**Class:** Sampler | **Method:** purgeMicPosition

> A multi-mic instrument purges/unpurges mic positions across all samplers based on a mode matrix (e.g., Classic uses all mics, Pop uses only Mid).

```javascript
// Context: A multi-mic instrument purges/unpurges mic positions across all samplers
// based on a mode matrix (e.g., Classic uses all mics, Pop uses only Mid).

const var NUM_MICS = 3;

const var samplers = [Synth.getSampler("Sustain"),
                      Synth.getSampler("Release"),
                      Synth.getSampler("Pedal")];

const var micGains = [Synth.getEffect("Close"),
                      Synth.getEffect("Mid"),
                      Synth.getEffect("Far")];

const var micNames = ["Close", "Mid", "Far"];

// Mode matrix: 1 = user-controlled, 0 = forced off, 2 = forced on
//                CLOSE  MID  FAR
const var MATRIX = [[1,    1,   1],   // Classic
                    [0,    2,   0],   // Pop
                    [0,    2,   2]];  // Cinematic

reg currentMode = 0;

inline function purgeMic(micIndex, shouldBeEnabled)
{
    // Purge the mic position across ALL samplers simultaneously
    for (s in samplers)
        s.purgeMicPosition(micNames[micIndex], !shouldBeEnabled);
}

inline function refreshAllMics()
{
    for (i = 0; i < NUM_MICS; i++)
    {
        local modeValue = MATRIX[currentMode][i];

        // 2 = forced on regardless of button, 0 = forced off, 1 = user choice
        if (modeValue == 2)
            purgeMic(i, true);
        else if (modeValue == 0)
            purgeMic(i, false);
        else
            purgeMic(i, micButtons[i].getValue());
    }
}
```

# Duration-based release group switching

**Class:** Sampler | **Method:** setActiveGroup

> A release sampler selects between short and long release samples based on how long the note was held. Short notes (< 0.8s) trigger group 1, longer notes trigger group 2.

```javascript
// Context: A release sampler selects between short and long release samples
// based on how long the note was held. Short notes (< 0.8s) trigger group 1,
// longer notes trigger group 2.

Sampler.enableRoundRobin(false);
Sampler.setActiveGroup(2); // Default to long release

const var uptimes = Engine.createMidiList();
const var holder = Engine.createMessageHolder();

// In onNoteOn: record the note start time
inline function handleNoteOn()
{
    uptimes.setValue(Message.getNoteNumber(), Engine.getUptime());
    Message.store(holder);
    Message.ignoreEvent(true);
}

// In onNoteOff: switch group based on hold duration, then replay
inline function handleNoteOff()
{
    Message.store(holder);

    local duration = Engine.getUptime() - uptimes.getValue(holder.getNoteNumber());
    local isShort = duration < 0.8;

    // Select the appropriate release group before triggering
    Sampler.setActiveGroup(isShort ? 1 : 2);

    holder.setGain(-6);
    Synth.addMessageFromHolder(holder);
}
```

# Convert envelope times to normalized path coordinates

**Class:** ScriptAudioWaveform | **Method:** getRangeEnd

> When overlaying an AHDR envelope shape on a waveform display, the total sample count from getRangeEnd() converts millisecond-based envelope parameters into normalized (0-1) path coordinates that align with the waveform width.

```javascript
// Context: When overlaying an AHDR envelope shape on a waveform display,
// the total sample count from getRangeEnd() converts millisecond-based
// envelope parameters into normalized (0-1) path coordinates that align
// with the waveform width.

const var wf = Content.addAudioWaveform("Waveform1", 0, 0);
const var overlay = Content.addPanel("EnvelopeOverlay", 0, 0);

inline function rebuildEnvelopePath(attackMs, holdMs, decayMs)
{
    local numSamples = wf.getRangeEnd();

    if (numSamples == 0)
        return;

    local sampleRate = 44100.0;

    // Convert ms envelope times to normalized fractions of the sample length
    local attackNorm = attackMs * 0.001 * sampleRate / numSamples;
    local holdNorm = holdMs * 0.001 * sampleRate / numSamples;
    local decayNorm = decayMs * 0.001 * sampleRate / numSamples;

    local p = Content.createPath();

    p.startNewSubPath(0.0, 0.0);
    p.startNewSubPath(1.0, 1.0);

    // Build envelope shape: silence -> attack -> hold -> decay -> silence
    local x = 0.0;
    p.startNewSubPath(x, 1.0);

    x += attackNorm;
    p.lineTo(Math.min(1.0, x), 0.0);

    x += holdNorm;
    p.lineTo(Math.min(1.0, x), 0.0);

    // Curved decay segment
    p.quadraticTo(Math.min(1.0, x + decayNorm / 3), 1.0,
                  Math.min(1.0, x + decayNorm), 1.0);
    p.lineTo(1.0, 1.0);

    overlay.data.envelopePath = p;
    overlay.repaint();
}

// With no audio loaded, getRangeEnd() returns 0 and the guard skips work
rebuildEnvelopePath(10, 20, 100);
```

