# Loading overlay with progress bar and spinner

**Class:** ScriptPanel | **Method:** setLoadingCallback

> A panel that shows a progress bar during sample preloading. The loading callback starts/stops a timer that polls the preload progress, and the paint routine draws both a progress bar and status text.

```javascript
// Context: A panel that shows a progress bar during sample preloading.
// The loading callback starts/stops a timer that polls the preload
// progress, and the paint routine draws both a progress bar and status text.

const var loadingBar = Content.addPanel("LoadingBar", 0, 0);
loadingBar.set("width", 300);
loadingBar.set("height", 40);
loadingBar.set("visible", false);

loadingBar.data.progress = 0.0;

loadingBar.setPaintRoutine(function(g)
{
    g.fillAll(0xFF1A1A1A);
    g.setColour(0xFF444444);

    local barArea = this.getLocalBounds(4);

    // Draw track
    g.drawRoundedRectangle(barArea, barArea[3] / 2, 1.0);

    // Draw filled portion
    local filled = [barArea[0] + 2, barArea[1] + 2,
                    (barArea[2] - 4) * this.data.progress, barArea[3] - 4];

    g.setColour(this.get("itemColour"));
    g.fillRoundedRectangle(filled, filled[3] / 2);

    // Draw percentage text
    local pct = parseInt(this.data.progress * 100) + "%";
    g.setColour(Colours.white);
    g.setFont("Arial", 12.0);
    g.drawAlignedText(pct, barArea, "centred");
});

loadingBar.setTimerCallback(function()
{
    this.data.progress = Engine.getPreloadProgress();
    this.repaint();
});

loadingBar.setLoadingCallback(function(isPreloading)
{
    if (isPreloading)
    {
        this.data.progress = 0.0;
        this.startTimer(30);
    }
    else
    {
        this.stopTimer();
    }

    // Show during loading, hide when done
    this.set("visible", isPreloading);
    this.repaint();
});
```

# Interactive threshold control with drag, double-click reset, and hover feedback

**Class:** ScriptPanel | **Method:** setMouseCallback

> A display panel where the user drags a vertical line to set a threshold. Demonstrates the full mouse event state machine: click sets initial value, drag updates continuously, double-click resets to default, hover changes cursor.

```javascript
// Context: A display panel where the user drags a vertical line to set a threshold.
// Demonstrates the full mouse event state machine: click sets initial value,
// drag updates continuously, double-click resets to default, hover changes cursor.

const var display = Content.addPanel("ThresholdDisplay", 0, 0);
display.set("width", 300);
display.set("height", 100);
display.set("allowCallbacks", "All Callbacks");

display.data.threshold = 0.5;
display.data.hover = false;
display.data.dragging = false;
display.data.downValue = 0.0;

const var thresholdKnob = Content.getComponent("ThresholdKnob");

display.setMouseCallback(function(event)
{
    this.data.hover = event.hover;

    if (event.clicked)
    {
        // Store starting value for drag offset calculation
        this.data.downValue = event.x / this.getWidth();
        this.data.threshold = this.data.downValue;
        this.data.dragging = true;
    }
    else if (event.doubleClick)
    {
        // Reset to default on double-click
        this.data.threshold = 0.5;
        thresholdKnob.setValue(0.5);
        thresholdKnob.changed();
    }
    else if (event.drag)
    {
        // Continuous update during drag
        local delta = event.dragX / this.getWidth();
        local newValue = Math.range(this.data.downValue + delta, 0.0, 1.0);
        this.data.threshold = newValue;
    }
    else if (event.mouseUp)
    {
        this.data.dragging = false;

        // Commit final value to the connected knob
        thresholdKnob.setValueNormalized(this.data.threshold);
        thresholdKnob.changed();
    }

    this.repaint();
});

display.setPaintRoutine(function(g)
{
    g.fillAll(0xFF27282A);

    // Draw threshold line
    local x = this.data.threshold * this.getWidth();
    local alpha = this.data.hover ? 0.8 : 0.4;
    g.setColour(Colours.withAlpha(this.get("itemColour"), alpha));
    g.fillRect([x, 0, 2, this.getHeight()]);

    // Draw border
    g.setColour(0xFF27282A);
    g.drawRoundedRectangle(this.getLocalBounds(0), 3.0, 2);
});
```

