{
    Message.store(holder);
    noteStack.insert(holder);
}

// In onNoteOff: pop the matching note-on event from the stack
inline function handleNoteOff()
{
    Message.store(holder);

    // removeIfEqual finds the matching event by ID and writes
    // the original note-on data back into the holder
    noteStack.removeIfEqual(holder);

    // holder now contains the original note-on event - use its
    // velocity, timestamp, etc. for release sample selection
    Synth.addMessageFromHolder(holder);
}
```

# Drain loop for releasing all held notes on pedal-off

**Class:** UnorderedStack | **Method:** storeEvent

> When a sustain pedal is released, all events in the stack must be processed and removed. storeEvent reads without removing, then removeElement clears the slot. Draining from index 0 avoids the index-shifting problems of forward iteration with removal.

```javascript
// Context: When a sustain pedal is released, all events in the stack
// must be processed and removed. storeEvent reads without removing,
// then removeElement clears the slot. Draining from index 0 avoids
// the index-shifting problems of forward iteration with removal.

const var noteStack = Engine.createUnorderedStack();
const var holder = Engine.createMessageHolder();
const var processedNotes = Engine.createMidiList();
noteStack.setIsEventStack(true, noteStack.EventId);

inline function drainOnPedalOff()
{
    processedNotes.clear();

    while (!noteStack.isEmpty())
    {
        // Read the event at index 0 into the holder
        noteStack.storeEvent(0, holder);

        // Remove index 0 (last element swaps in, stack shrinks by 1)
        noteStack.removeElement(0);

        // Deduplicate: skip if this note number was already processed
        // (handles edge case of multiple events for the same pitch)
        if (processedNotes.getValue(holder.getNoteNumber()) == -1)
        {
            processedNotes.setValue(holder.getNoteNumber(), 1);
            Synth.addMessageFromHolder(holder);
        }
    }
}
```

# Dynamic automation callback binding for a switchable XY pad

**Class:** UserPresetHandler | **Method:** attachAutomationCallback

> When a control switches which channel it displays (e.g., an XY pad that follows the selected channel), the automation callbacks need to be rebound. First remove old callbacks by passing an empty string, then attach new ones for the current channel's automation IDs.

```javascript
// Context: When a control switches which channel it displays (e.g., an XY pad
// that follows the selected channel), the automation callbacks need to be
// rebound. First remove old callbacks by passing an empty string, then
// attach new ones for the current channel's automation IDs.

const var uph = Engine.createUserPresetHandler();

// On channel switch: rebind the XY pad to the new channel's automation slots
inline function onChannelSwitch(panel, channelIndex)
{
    // Remove previous callbacks by passing a non-function value
    if (isDefined(panel.data.xId))
        uph.attachAutomationCallback(panel.data.xId, "", false);

    if (isDefined(panel.data.yId))
        uph.attachAutomationCallback(panel.data.yId, "", false);

    // Build new automation IDs for the selected channel
    panel.data.xId = "Mixer " + (channelIndex + 1) + " X";
    panel.data.yId = "Mixer " + (channelIndex + 1) + " Y";

    // Attach async callbacks that update the panel display
    uph.attachAutomationCallback(panel.data.xId, function [panel](index, value)
    {
        local v = panel.getValue();
        v[0] = value;
        panel.setValue(v);
        panel.repaint();
    }, AsyncNotification);

    uph.attachAutomationCallback(panel.data.yId, function [panel](index, value)
    {
        local v = panel.getValue();
        v[1] = value;
        panel.setValue(v);
        panel.repaint();
    }, AsyncNotification);

    // Read current values to initialize the display
    local allValues = uph.createObjectForAutomationValues();
    local xIdx = uph.getAutomationIndex(panel.data.xId);
    local yIdx = uph.getAutomationIndex(panel.data.yId);

    panel.setValue([allValues[xIdx].value, allValues[yIdx].value]);
    panel.repaint();
}
```

# Channel copy/paste using automation value snapshots

**Class:** UserPresetHandler | **Method:** createObjectForAutomationValues

> In a multi-channel instrument, copying a channel's settings to another channel requires capturing all automation values for the source channel, then applying them to the target. createObjectForAutomationValues() provides the full snapshot; the script filters and remaps by channel.

```javascript
// Context: In a multi-channel instrument, copying a channel's settings to
// another channel requires capturing all automation values for the source
// channel, then applying them to the target. createObjectForAutomationValues()
// provides the full snapshot; the script filters and remaps by channel.

const var uph = Engine.createUserPresetHandler();

inline function copyChannel(sourceIndex, targetIndex)
{
    local allValues = uph.createObjectForAutomationValues();
    // allValues is: [{"id": "Gain A1", "value": -6.0}, {"id": "Pan A1", "value": 0.5}, ...]

    local sourceTag = " " + (sourceIndex + 1);
    local targetTag = " " + (targetIndex + 1);

    for (slot in allValues)
    {
        // Find slots belonging to the source channel
        if (slot.id.indexOf(sourceTag) != -1)
        {
            // Remap the ID to the target channel
            local targetId = slot.id.replace(sourceTag, targetTag);
            local targetIdx = uph.getAutomationIndex(targetId);

            if (targetIdx >= 0)
                uph.setAutomationValue(targetIdx, slot.value);
        }
    }
}
```

