	g.setGradientFill([0xFFAAAAAA, 0.0, 0.0, 0xFF777777, 0.0, w, false]);
	g.rotate(r, [obj.area[2]/2, obj.area[3]/2]);
	g.fillEllipse(b.reduced(0.22*w));
	g.fillTriangle(b.withSizeKeepingCentre(0.15 * w, 0.1 * w).translated(0, -0.29 * w), 0.0);
	g.rotate(-r, [obj.area[2]/2, obj.area[3]/2]);
	g.setColour(0xAA000000);
	g.fillEllipse(b.reduced(0.28 * w));
	g.setColour(obj.textColour);

	paths[1].addArc(b.reduced(0.1 * w), -ARC + obj.modMinValue * 2.0 * ARC, -ARC + obj.modMaxValue * 2.0 * ARC);
	g.setColour(0x22FFFFFF);
	g.drawPath(paths[1], b, p);

	if(obj.modulationActive)
	{
		var mv = (obj.scaledValue + obj.addValue);
		var lm = obj.lastModValue;

		lmv = lm;
		lv = mv;

		paths[2].addArc(b.reduced(0.1 * w), -ARC + lm * 2.0 * ARC, -ARC + mv * 2.0 * ARC);

		var brightness = mv - lm;
		var modRange = obj.modMaxValue - obj.modMinValue;

		var alpha = Math.range(1.0 - brightness / modRange, 0.0, 1.0);
		g.setColour(Colours.withAlpha(Colours.white, alpha * 0.1));
		p.Thickness = 10;
		g.drawPath(paths[2], b, p);

		p.Thickness = 5;
		g.setColour(Colours.white);
		g.drawPath(paths[2], b, p);

		g.setColour(Colours.withAlpha(Colours.white, alpha * 0.1));
		p.Thickness = 15;

	}

	g.setColour(Colours.white);
	g.drawAlignedText(obj.hover ? obj.valueAsText : obj.text, b, "centredBottom");
});

