# Control current EQ band

**Category:** Modules

**Tags:** Best Practice, Broadcaster, Complex, UI Logic

This snippet will demonstrate how to mirror the functionality of the knobs on the Curve EQ interface which will follow the band selection.

It uses two broadcasters to sync the Panel with the knobs.

```javascript
Content.makeFrontInterface(500, 300);

namespace EQWatcher
{

// This broadcaster will notify the sliders when you click on another
// band to update their connection
const var currentBandWatcher = Engine.createBroadcaster({
  "id": "currentBandWatcher",
  "args": ["eventType", "value"],
  "tags": []
});

// This broadcaster will watch over the current parameters and update the
// knobs so that they stay in sync when you drag in the panel
const var eqParameterWatcher = Engine.createBroadcaster({
  "id": "eqParameterWatcher",
  "args": ["processor", "parameter", "value"],
  "tags": []
});

// We need to enable the queue so that all events will go through 
// (if you drag a handle, it will send the parameter updates for gain, frequency and Q at once)
eqParameterWatcher.setEnableQueue(true);

// Grab the reference to the EQ
const var ParametriqEQ1 = Synth.getEffect("Parametriq EQ1");

// attach to event Type
currentBandWatcher.attachToEqEvents(["Parametriq EQ1"], ["BandAdded", "BandSelected", "BandRemoved"], "");

// This stores the indexes for the parameter offsets in an array that matches
// the knob array
const var PARAMETER = [ParametriqEQ1.Freq, ParametriqEQ1.Q, ParametriqEQ1.Gain];

// This stores the knobs in an array that matches the parameter array.
const var KNOB_LIST = [Content.getComponent("CurrentFrequency"), Content.getComponent("CurrentQ"), Content.getComponent("CurrentGain")];

inline function onKnobControl(component, value)
{
	// Grab the index in the knob list
	local idx = KNOB_LIST.indexOf(component);

	// Get the parameter offset from the parameter list
	local type = PARAMETER[idx];

	// Calculate the actual parameter index that we send to the
	// EQ
	local parameter = ParametriqEQ1.BandOffset * currentBand + type;

	// Check that it's positive (might be -1 at the start)
	if(parameter >= 0)
	{
		ParametriqEQ1.setAttribute(parameter, value);
	}	
};

// Stores the current band selection
reg currentBand = -1;

for(k in KNOB_LIST)
	k.setControlCallback(onKnobControl);

// This will be called when the band selection changes
inline function updateBands(unused, value)
{
	currentBand = value;

	if(value >= 0)
	{
		// Calculate the parameter indexes that we want to watch
		local freqIndex = ParametriqEQ1.BandOffset * value + ParametriqEQ1.Freq;
		local qIndex = ParametriqEQ1.BandOffset * value + ParametriqEQ1.Q;
		local gainIndex = ParametriqEQ1.BandOffset * value + ParametriqEQ1.Gain;

		// Redirect the parameter watcher to listen to changes for the parameters
		// that are currently connected to the knobs
		eqParameterWatcher.removeAllSources();
		eqParameterWatcher.attachToModuleParameter("Parametriq EQ1", [freqIndex, qIndex, gainIndex], "sync the knobs");
	}
}

currentBandWatcher.addListener(eqParameterWatcher, "update the band", updateBands);

// This will be called when a module parameter of the currently selected band changes
inline function updateKnob(unused, parameter, value)
{
	// grab the "raw" parameter index
	local parameterIndex = parameter % ParametriqEQ1.BandOffset;
	// fetch the knob we want to update
	local knobIndex = PARAMETER.indexOf(parameterIndex);

	// update the knob
	this[knobIndex].setValue(value);
}

eqParameterWatcher.addListener(KNOB_LIST, "update the parameter watcher", updateKnob);

}





