# Midi Player Step Sequencer

**Category:** MIDI

**Tags:** API, MIDI Player

A minimal example that shows how to use the MIDI player to implement a basic step sequencer.

```javascript
Content.makeFrontInterface(800, 100);

const var MIDIPlayer1 = Synth.getMidiPlayer("MIDI Player1");

// Important: this makes the MIDI player use Ticks (960 / quarter note) instead of samples. Using this domain makes the calculation much more easy
MIDIPlayer1.setUseTimestampInTicks(true);

const var NUM_PER_SIXTEEN = 960 / 4;
const var NUM_STEPS = 16;

// Setup the sequence to hold 16 steps
MIDIPlayer1.clearAllSequences();
MIDIPlayer1.create(4, 4, NUM_STEPS / 16);

// Now we'll create a minimal step sequencer consisting of 16 buttons
// there are 100 better ways to implement this, but this is the most simple one.
const var STEPS = [];

for(i = 0; i < NUM_STEPS; i++)
	STEPS.push(Content.addButton("Step" + (i + 1), i * 50, 0));

reg idx = 1;

inline function rebuildSequence()
{
	Console.print("rebuild");

	// Create a array that we'll fill with message objects
	local list = [];
	local ts = 0;

	for(s in STEPS)
	{
		if(s.getValue())
		{
			// Create a note on and off message
			local on = Engine.createMessageHolder();
			local off = Engine.createMessageHolder();

			// set the type, note number & velocity for both
			on.setType(Message.NoteOn);
			off.setType(Message.NoteOff);
			on.setVelocity(127);
			on.setNoteNumber(64);
			off.setNoteNumber(64);

			// now we set the timestamp for both the on and off message
			on.setTimestamp(ts );
			off.setTimestamp(ts + NUM_PER_SIXTEEN * 0.5);

			// add both messages
			list.push(on);
			list.push(off);
		}

		// bump the timestamp
		ts += NUM_PER_SIXTEEN;
	}

	// This function will create a new sequence from the given array
	MIDIPlayer1.flushMessageList(list);
}

// Implement a simple position visualizer
const var to = Engine.createTimerObject();

var lastPos = 0;

to.setTimerCallback(function()
{
	var pos = parseInt(STEPS.length * MIDIPlayer1.getPlaybackPosition());

	if(MIDIPlayer1.getPlayState() == 0)
		pos = -1;

	if(lastPos == pos)
		return;

	lastPos = pos;

	for(i = 0; i < STEPS.length; i++)
		STEPS[i].set("bgColour", i == pos ? 0xFF999999 : 0xFF222222);
});

to.startTimer(60);

inline function onButton(component, value)
{
	// Note: this is not very performant and will cause the MIDI sequence to be rebuild 16 times whenever you load a preset
	// In a real world project you probably use a slider pack or a single ScriptPanel for the sequencer UI
	rebuildSequence();
}

for(s in STEPS)
{
	s.set("width", 50);
	s.set("height", 50);
	s.set("text", idx++);
	s.setControlCallback(onButton);
}

// Add a simple MIDI playback controller

const var PLAY = Content.addButton("PLAY", 10, 60);

inline function onPlay(component, value)
{
	if(value)
		MIDIPlayer1.play(0);
	else
		MIDIPlayer1.stop(0);
}

PLAY.setControlCallback(onPlay);

