// ==========================================================================

// Just a small helper function that plays a note with a defined length
inline function playNote(noteNumber, velocity, timestamp, length)
{
	local newId = Synth.addNoteOn(1, Math.range(noteNumber, 0, 126), velocity, timestamp);
	Synth.noteOffDelayedByEventId(newId, timestamp + length);

	return newId;
}

// This will be executed on the grid callback of the transport handler
// and will implement the arpeggiator logic
inline function gridCallback(index, timestamp, isFirst)
{
	// Set the current direction to the one we want
	// if this is the first time the grid callback is called after starting
	// the transport handler
	if(isFirst)
		currentInverse = inverse;

	if(sortedList.isEmpty())
	{
		// Skip empty notes when running as external clock
		return;
	}

	local packLength = NumSteps.getValue();
	local packIndex = index % packLength;
	local noteListLength = sortedList.size();
	local noteIndex = index % noteListLength;

	if(swapInverse && noteIndex == 0)
		currentInverse = !currentInverse;

	if(currentInverse)
		noteIndex = noteListLength - 1 - noteIndex;

	if(randomNote)
		noteIndex = Math.randInt(0, noteListLength-1);

	local durationMs = Engine.getMilliSecondsForTempo(tempo.getValue());
	local durationSamples = Engine.getSamplesForMilliSeconds(durationMs);
	local transpose = PitchPack.getSliderValueAt(packIndex);
	local velo = VelocityPack.getSliderValueAt(packIndex) * 127;

	// We need to copy it because we can't modify inline function arguments
	local ts = timestamp;

	// Calculate the swing
	local thisSwing = swing.getValue() * 0.8;

	if(index % 2 == 1 && thisSwing > 0.0)
	{
		ts += durationSamples * thisSwing * 0.5;
		durationSamples *= (1.0 - thisSwing);
	}

	durationSamples *= LengthPack.getSliderValueAt(packIndex);

	if(chordMode)
	{
		firstChord = isFirst;

		// Just iterate the entire note list and play every note at every grid
		for(s in sortedList)
		{
			local id = playNote(s.noteNumber + transpose, velo, ts, durationSamples);
			sendAdditionalLaneData(id, packIndex);
		}
	}
	else
	{
		// fetch the note from the list, apply the velocity, pitch and length changes
		// and play the note
		local id = playNote(sortedList[noteIndex].noteNumber + transpose, velo, ts, durationSamples);
		sendAdditionalLaneData(id, packIndex);
	}
};

// This will pass on the function to be called at every grid callback. It's extremely important
// to use the synchronous execution mode to ensure proper timing (feel free to comment out the other)
// function call below and listen how the arpeggiator will get jittery when played with fast speed.
th.setOnGridChange(SyncNotification, gridCallback);
//th.setOnGridChange(AsyncNotification, gridCallback);

//! DATA LOGIC
// ========================================================================================================

// Let's create a fix object factory again
const var f = Engine.createFixObjectFactory({
	"noteNumber": -1, // used for sorting
	"velocity": 0,    // not used at the moment
	"id": -1,		  // used for identifier note on / off pairs for removal
	"uptime": 0.0     // used for sorting by order
});

const var scratch = f.create();
const var activeNotes = f.createStack(32);
const var heldNotes = f.createStack(32);
const var sortedList = f.createStack(256);

const var rm = Engine.getGlobalRoutingManager();

/** This writes the lane data to the additional storage object. */
inline function sendAdditionalLaneData(eventId, packIndex)
{
	local idx = 0;

	for(ad in additionalData)
		rm.setEventData(eventId, idx++, ad.getValue(packIndex));
}

inline function playAdditionalFirstChordNotes(noteNumber)
{
	local velo = VelocityPack.getSliderValueAt(0) * 127;
	local transpose = PitchPack.getSliderValueAt(0);
	local durationMs = Engine.getMilliSecondsForTempo(tempo.getValue());
	local durationSamples = Engine.getSamplesForMilliSeconds(durationMs) * LengthPack.getSliderValueAt(0);

	for(i = 0; i < numOctaves.getValue(); i++)
	{
		local id = playNote(noteNumber + transpose + i * 12, velo, 0, durationSamples);
		sendAdditionalLaneData(id, 0);
	}

}

inline function rebuildSortedList()
{
	// Clear the sorted list
	sortedList.clearQuick();

	// Sort the notes before stacking them up in the octaves
	activeNotes.sort();

	// for each octave, insert the sorted list into the note array
	for(i = 0; i < numOctaves.getValue(); i++)
	{
		for(s in activeNotes)
		{
			// Copy all relevant properties (currently we don't)
			// use the velocity property at all, but that can be
			// used for further customization
			scratch.noteNumber = s.noteNumber + i * 12;
			scratch.id = s.id;
			scratch.velocity = s.velocity;
			sortedList.insert(scratch);
		}
	}
};

// Called by the onNoteOn callback
inline function handleNoteOn()
{
	if(!enabled.getValue())
			return;

	Message.ignoreEvent(true);

	// Set all data members of the scratch object to
	// our current note info
	scratch.id = Message.getEventId();
	scratch.noteNumber = Message.getNoteNumber();
	scratch.velocity = Message.getVelocity();
	scratch.uptime = Engine.getUptime();

	// check whether we should start the clock
	// Note: we need to check this here and then 
	// start the transport handler after inserting the
	// note because otherwise it will be executed
	// on an empty list for the first grid callback
	local startInternalClock = activeNotes.isEmpty();

	activeNotes.insert(scratch);
	rebuildSortedList();

	if(startInternalClock)
	{
		th.startInternalClock(Message.getTimestamp());
	}

	// This allows us to play the other notes of the first chord
	// in chord mode (because the first note will trigger the first
	// grid callback so the first "chord" would only be a single note
	if(firstChord && activeNotes.size() > 1)
	{
		playAdditionalFirstChordNotes(Message.getNoteNumber());
	}
}

inline function handleNoteOff()
{
	if(!enabled.getValue())
		return;

	Message.ignoreEvent(true);

	// check the event id in the active note list
	// and either remove it or push it to the list
	// of held notes (which will be released when the
	// hold button is unticked).
	for(s in activeNotes)
	{
		if(s.id == Message.getEventId())
		{
			if(hold.getValue())
				heldNotes.insert(s);
			else
				activeNotes.remove(s);

			break;
		}
	}

	rebuildSortedList();

	// if no notes are present we can stop the internal clock
	if(activeNotes.isEmpty())
		th.stopInternalClock(Message.getTimestamp());
}

}
function onNoteOn()
{
	SyncedArpeggiator.handleNoteOn();
}

function onNoteOff()
{
	SyncedArpeggiator.handleNoteOff();
}

