inline function LoadUserDataFile () {

	// ======================================== Prepare

	local validUserDataFileExisted = null;
	local userAppData = {};

	Console.print("{Looking for user file…}");

	// Get a reference to the App Data folder.
	local appDataFolder = FileSystem.getFolder(FileSystem.AppData);

	// Get a reference to the file. If it doesn't exist, create it.
	local userDataFile = appDataFolder.getChildFile(USER_APPDATA_FOLDER_NAME);

	// ================================== Check if the File Exists

	if (userDataFile.isFile()) {	

		// ------------- Data File Existed

		// Log.
		Console.print("{File with correct name of User Data file found.}");

		// There's a file. Try to load the JSON data.
		userAppData = userDataFile.loadAsObject();

		// Check if the data file is valid.
		if (TestIfUserDataFileValid(userAppData)) {

			// ------------- Data File Is Valid

			// Log.
			Console.print("{User Data file is valid.}");

			// A valid file existed.
			validUserDataFileExisted = true;

		} else {

			// ------------- Data File Is Not Valid

			// Log.
			Console.print("{User Data file is not valid; create a new one.}");

			// A valid file didn't exist.
			validUserDataFileExisted = false;
		} 

	} else {

		// ------------- User Data File Does Not Exist

		// Log.
		Console.print("{File with User Data filename not found; create new file.}");

		// A valid file didn't exist.
		validUserDataFileExisted = false;
	}

	// ================================== Create the File?

	if (!validUserDataFileExisted) {

		// Create the data object.
		g_userAppData = CreateUserDataJsonObject ();

		WriteUserDataFile ();

	} else {

		// Assign the global.
		g_userAppData = userAppData;
	}	

	// ================================== Assigning the global file.

	g_userDataFile = userDataFile;

	// ================================== Returning if File Existed.

	return validUserDataFileExisted;
};

