inline function EvaluateIfCheckForAppUpdate () {

	// ================================== User Data File Creation Check

	// If the preference for checking for updates is true, then check.
	if (button_checkForUpdates.getValue()==COMBO_ON) {

		// Record today's date.
		local dateToday = Date.getSystemTimeISO8601(false).substring(0,8);

		// Log.	
		Console.print("{Checking when last update comparison was made [" + g_userAppData.update.lastUpdateCheck + "] Today [" + dateToday + "]}");	

		// Compare the date (day) of the last update check with today's date (day), or if there was any previous check.
		if ( (g_userAppData.update.lastUpdateCheck < dateToday) || (g_userAppData.update.lastUpdateCheck == null) ){

			Console.print("> New version was checked for today [False]");

			// Its been at least one day; check for an update.
			UpdateIfNewerVersionAvailable();

		} else {  

			// Log.
			Console.print("> New version was already checked for today [True]");
		}
	}

	// ================================== Revising the User Data File

	ReviseUserDataFile("last_update_check");
}

