# Continuous Per-Event Modulation

**Category:** Scriptnode

**Tags:** Broadcaster, Complex, Internal Messaging

Sets up HISEs Event system for continuous per-event modulation in a detunable Scriptnode Synth. There is a lot to learn about HISE advanced features.


by aaronventure

[Forum Topic](https://forum.hise.audio/topic/9645/the-missing-piece-of-the-hise-vi-puzzle-continuous-per-event-modulation)

```javascript
Content.makeFrontInterface(600, 600);

// Makes the note on, note off, timer, controller callbacks non-realtime
// This is only useful if we're gonna use these callbacks to affect the interface
Synth.deferCallbacks(true);

// Our global event that we can access from anywhere
// Because HISE doesn't destroy global variables on F5 compile, it's easy to get them working when declared anywhere
// But for export they should always be declared first
global Event = {};

// Create an array for storing note ids. 
// Reserve the space because dynamic array resizing is unnecessarily expensive and should be avoided at all costs in realtime operations
Event.noteIds = []; 
Event.noteIds.reserve(128);

// We need more than one event per note so we're creating 128 arrays inside our main id array, each with 32 slots
for (i = 0; i<128; i++)
{
	Event.noteIds[i] = [];
	Event.noteIds[i].reserve(32);
}

// Here we can be storing our control values for global access
global ControlValue = {};

// ======================================

// We will use this to store event related data
const globalRouting = Engine.getGlobalRoutingManager();

// ======================================


// Broadcaster definition
const var valueChangeBroadcaster = Engine.createBroadcaster({
  "id": "valueChangeBroadcaster",
  "args": ["component", "value"],
  "tags": []
});

// We don't want to miss any value changes
valueChangeBroadcaster.setEnableQueue(true);

// Since we're gonna be using the global values in the realtime callback, let's make sure that they really are what the UI is showing
valueChangeBroadcaster.setForceSynchronousExecution(true);

inline function attachValueChangeBroadcaster(component)
{
	valueChangeBroadcaster.attachToComponentValue([component], ""); 
}

// This function will execute every time an attached component's value changes
valueChangeBroadcaster.addListener(false, "Globalize Value", function(component, value)
{
	ControlValue[component.get("id")] = value;
});

// ======================================

inline function setEventDetune(voiceNum, value)
{
	local i = 0;

	// check all notes
	for (i in Event.noteIds)
	{
		// if a note is playing i.e. id exists and isn't -1, which we set in note off
		if (isDefined(i[voiceNum]) && i[voiceNum] != -1)
		{
			// set the target detune
			// this is present in the scriptnode synth and affects the tuning
			globalRouting.setEventData(i[voiceNum], 0, value);
		}
	}
}


const detune1 = Content.addKnob("detune1", 0, 0);
Content.setPropertiesFromJSON("detune1", 
{
	"min": -100,
	"max": 100,
}); 

// attach to the value change broadcaster so that we don't have to manually copy the function into each control callback
// this scales very well as it can be added to a control helper function and you can then forget about it
attachValueChangeBroadcaster(detune1);

inline function ondetune1Control(component, value)
{
	setEventDetune(0, value);
};

Content.getComponent("detune1").setControlCallback(ondetune1Control);


// Detune 2
const detune2 = Content.addKnob("detune2", 200, 0);
Content.setPropertiesFromJSON("detune2", 
{
	"min": -100,
	"max": 100,
}); 
attachValueChangeBroadcaster(detune2);

inline function ondetune2Control(component, value)
{
	setEventDetune(1, value);
};

Content.getComponent("detune2").setControlCallback(ondetune2Control);


