# Modwheel and Pitchwheel UI components

**Category:** UI

**Tags:** Best Practice, Graphics API, UI Logic

A snippet that implements a modwheel and pitch bend UI component. It reacts to incoming MIDI messages and also sends out the MIDI values to control the internal engine.

> Note that this doesn't work with MIDI assignments via the MIDI learn popup as they require "real" MIDI events from the outside world.

```javascript
Content.makeFrontInterface(300, 100);

// Don't want this to derail our audio performance...
Synth.deferCallbacks(true);

const var MODWHEEL_LAF = Content.createLocalLookAndFeel();

MODWHEEL_LAF.registerFunction("drawRotarySlider", function(g, obj)
{
	/// for a slider size 20x60

	//Console.print(trace(obj));

    var x = 5; // 1/4 of the slider width.  Useful if you change the width
    var wheelWidth = 10;  //  Width of the actual wheel.  This leaves 5px of space either side.
    var a = obj.area;

    // Value to use for the movement of the horizontal lines / wheel and create padding top and bottom

	var totalTravel = 51;  // total movement of the handle, less top padding
	var bottomPad = 2;     // prevent handle reaching bottom
	var v = (obj.value * totalTravel) + bottomPad;
    // var v = ((obj.value / 16383) * totalTravel) + bottomPad;  // PitchWheel calc which has range of 0-16383

    var numLines = 60; // number of horizontal lines
    var lineSpacing = 2; // distance between lines

	var bgColour = 0xFB080910; // Background Colour
	var wheelColour = 0xFF0F7691;  // The colour of the Wheel itself
	var shadeColour = 0xFF0B0925;  // Dark shading colour
	var lightColour = 0x38FFFFFF;  // Lighting effect colour

    // Background Fill
    g.setColour(bgColour);
    g.fillRect(obj.area);

    // Wheel Background to be dark
    g.setColour(Colours.black);
    g.fillRect([x, 0, wheelWidth, a[3]]);

	// Wheel Sides
	g.setColour(0xFB24252B);  // Dark Grey
	g.drawVerticalLine(3, 0, 60);
	g.drawVerticalLine(16, 0, 60);

    // Draw the ModWheel lines

    g.setColour(wheelColour);

    for (var i = 0; i < numLines; i++)
    {
        var y = (2 * i) - v;  
        g.drawHorizontalLine(y, x, wheelWidth + x);
    }

    // Handle Background - fill in the odd numbered lines to make the handle
	g.setColour(wheelColour);

	g.drawHorizontalLine(53 - v, x, wheelWidth + x); 
	g.drawHorizontalLine(55 - v, x, wheelWidth + x); 
	g.drawHorizontalLine(57 - v, x, wheelWidth + x); 
	g.drawHorizontalLine(59 - v, x, wheelWidth + x);

	// White Handle Bar if you want it under the Lighting Gradients

    //  g.setColour(Colours.white);
    //  g.drawHorizontalLine(56 - v, x + 2, width - 2);

    // Gradient Overlay (top & bottom shading and lighting)

    g.setGradientFill([0xFF181515, 6, 0, 0x00000000, 6, 15]); // Shade Top
    g.fillRect(obj.area);

    g.setGradientFill([0x00000000, 6, 30, shadeColour, 6, 60]); // Shade Bottom
    g.fillRect(obj.area);

    g.setGradientFill([0x00000000, 6, 0,lightColour, 6, 15]); // Light Top
    g.fillRect([x, 0, wheelWidth, 15]);

    g.setGradientFill([lightColour, 6, 15, 0x00000000, 6, 40]);  // Light a little further down
    g.fillRect([x, 15, wheelWidth, 30]); 

    // White Handle Bar if you want it on top of the Lighting Gradients

    g.setColour(Colours.white);
    g.drawHorizontalLine(56 - v, x - 1, wheelWidth + x + 1); 

    // Black Box Surround, unaffected by lighting effects
    g.setColour(Colours.black);
    g.drawRect(a, 1);


});

