# ModulationDisplay

**Category:** UI

**Tags:** Best Practice, Complex, Featured, Graphics API, UI Logic, Modulation

This example shows how to use the new combined modulation mode to visualize a modulated value on a knob ring.

It uses a custom LAF and the `Knob1.connectToModulatedParameter()` method.

The modulation source is the mix modulation chain of the waveform generator with a bunch of modulators added to it.

```javascript
Content.makeFrontInterface(600, 200);

const var laf = Content.createLocalLookAndFeel();


const var Knob1 = Content.getComponent("Knob1");

// This function will connect the knob to the modulation chain associated
// with the Mix parameter of the waveform generator. This will cause it to
// repaint periodically when the mod value changes and add two new properties
// to the LAF object that can be used to display the modulated value
Knob1.connectToModulatedParameter("Waveform Generator1", "Mix");

const var ARC_START = 2.3;

laf.registerFunction("drawRotarySlider", function(g, obj)
{
	//Console.print(trace(obj));

	var rings = [];
	rings.reserve(8);

	// let's create a bunch of paths
	rings.push(Content.createPath()); // value track
	rings.push(Content.createPath()); // scale track
	rings.push(Content.createPath()); // mod track
	rings.push(Content.createPath()); // full track
	rings.push(Content.createPath()); // value
	rings.push(Content.createPath()); // scaled mod value
	rings.push(Content.createPath()); // bipolar / unipolar add value
	rings.push(Content.createPath()); // full value

	// start subpaths so that the path is always scaled to the full obj.area bounds
	for(r in rings)
	{
		r.startNewSubPath(obj.area[0], obj.area[1]);
		r.startNewSubPath(obj.area[2], obj.area[3]);
	}

	// Uncomment this is and you'll be spammed with all properties
	//Console.print(trace(obj));

	// this is the outer ring
	var ringBounds = Rectangle(obj.area).reduced(20);

	// this is the value position of the scaled modulation value
	// it uses the obj.scaledValue property which is available when the modulation is connected
	var scaleModValue =  -ARC_START + obj.scaledValue * 2.0 * ARC_START;

	// this will calculate the final value by applying the unipolar / bipolar offset to the chain
	var addModValue = scaleModValue + obj.addValue * 2.0 * ARC_START;

	// lets add 4 full tracks with different sizes
	rings[0].addArc(ringBounds, -ARC_START, ARC_START);
	rings[1].addArc(ringBounds.reduced(-5), -ARC_START, ARC_START);
	rings[2].addArc(ringBounds.reduced(-10), -ARC_START, ARC_START);
	rings[3].addArc(ringBounds.reduced(-15), -ARC_START, ARC_START);

	// zero to UI position (grey)
	rings[4].addArc(ringBounds, -ARC_START, -ARC_START + obj.valueNormalized * 2.0 * ARC_START);
	// zero to scaled position (red)
	rings[5].addArc(ringBounds.reduced(-5), -ARC_START, scaleModValue);
	// scaled position to offset position (yellow)
	rings[6].addArc(ringBounds.reduced(-10), scaleModValue, addModValue);
	// zero to final value position (white)
	rings[7].addArc(ringBounds.reduced(-15), -ARC_START, addModValue);


	g.setColour(0x22FFFFFF);
	g.drawPath(rings[0], obj.area, 3);
	g.drawPath(rings[1], obj.area, 3);
	g.drawPath(rings[2], obj.area, 3);
	g.drawPath(rings[3], obj.area, 3);

	g.setColour(Colours.grey); // zero to UI
	g.drawPath(rings[4], obj.area, 3.0);
	g.setColour(Colours.red); // zero to scaled
	g.drawPath(rings[5], obj.area, 3.0);
	g.setColour(Colours.yellow); // scaled to offset
	g.drawPath(rings[6], obj.area, 3.0);
	g.setColour(Colours.white); // zero to offset
	g.drawPath(rings[7], obj.area, 3.0);

	g.setColour(obj.textColour);
	g.drawAlignedText(obj.valueAsText, obj.area, "centred");
});

Knob1.setLocalLookAndFeel(laf);


