# ScriptPanel Drag Example

**Category:** UI

**Tags:** ScriptPanel, UI Logic, Modulation

This example demonstrates how to use the internal drag feature of a ScriptPanel to implement drag & drop functions across multiple UI elements.

```javascript
Content.makeFrontInterface(600, 100);

// a simple paint routine
inline function paint(g)
{
	g.fillAll(this.get("bgColour"));
	g.setColour(Colours.white);
	g.drawAlignedText(this.get("text"), this.getLocalBounds(0), "centred");
}

// setup the panels
const var Source = Content.getComponent("Source");
const var Target = Content.getComponent("Target");
const var Illegal = Content.getComponent("Illegal");

Source.set("bgColour", Colours.blue);
Target.set("bgColour", Colours.green);
Illegal.set("bgColour", Colours.red);

Source.setPaintRoutine(paint);
Target.setPaintRoutine(paint);
Illegal.setPaintRoutine(paint);

// set the source to listen to mouse callbacks and change the cursor to the
// dragging hand
Source.set("allowCallbacks", "Clicks, Hover & Dragging");
Source.setMouseCursor("DraggingHandCursor", Colours.white, [0, 0]);

// this function will be called to render a drag image. This is called whenever
// you call Content.refreshDragImage()
function dragPaint(g, obj)
{
	var isValid = obj.valid;
	isValid |= obj.target.length == 0;
	isValid |= obj.target == obj.source;
	g.fillAll(isValid ? Colours.white : Colours.red);
}

// this function will be executed whenever the object was dropped on something
function onDrag(isValid, targetName)
{
	Console.print(isValid ? targetName : "Cancelled");
}

// this function will be called to check whether the 
// drag target is valid. It will be executed whenever you hover
// over a different object
function checkValid(targetId)
{
	// we want to update the drag image to reflect the draggability
	Content.refreshDragImage();
	return targetId == "Target";
}

Source.setMouseCallback(function(event)
{
	if(event.clicked && !event.rightClick)
	{
		// on left mouse down we'll call this method once
		// and the dragging will be handled automatically
		Source.startInternalDrag({
			area: [0, 0, 50, 50],    // the size of the drag image
			paintRoutine: dragPaint, // the paint function that renders the dragged image
			dragCallback: onDrag,    // the callback that is executed when dropped
			isValid: checkValid      // the function that checks the draggability on hover
		});
	}
});
