# Knob with Modulation scaling 2

**Category:** UI

**Tags:** UI Logic

Another knob LAF that uses the modulation display ring.

```javascript
Content.makeFrontInterface(200, 200);

const var Knob1 = Content.getComponent("Knob1");
Knob1.connectToModulatedParameter("Waveform Generator1", "Mix");

const var laf = Content.createLocalLookAndFeel();

const var ARC = 2.3;
const var LENGTH = 2.0 * ARC;

inline function modSlider(g, obj)
{
	local arcs = [];
	local r = Rectangle(1.0, 1.0);

	arcs.push(Content.createPath()); // the full track
	arcs.push(Content.createPath()); // the value arc
	arcs.push(Content.createPath()); // the mod arc
	arcs.push(Content.createPath()); // the mod range arc

	for(a in arcs)
	{
		a.startNewSubPath(0.0, 0.0);
		a.startNewSubPath(1.0, 1.0);
	}

	local v = -ARC + LENGTH * obj.valueNormalized;

	arcs[0].addArc(r, -ARC, ARC);
	arcs[1].addArc(r, -ARC, v);
	arcs[2].addArc(r, -ARC + LENGTH * (obj.scaledValue + obj.addValue), v);
	arcs[3].addArc(r, -ARC + LENGTH * obj.modMinValue, -ARC + LENGTH * obj.modMaxValue);
	local area = Rectangle(obj.area);

	g.setColour(obj.bgColour);
	g.fillEllipse(area);


	g.drawPath(arcs[0], area.reduced(10.0), 10.0);
	g.setColour(obj.itemColour1);
	g.drawPath(arcs[1], area.reduced(10.0), 7.0);
	g.setColour(0x22FFFFFF);
	g.drawPath(arcs[3], area.reduced(18.0), 3.0);
	g.setColour(Colours.white);
	g.drawPath(arcs[2], area.reduced(18.0), 3.0);
};

laf.registerFunction("drawRotarySlider", modSlider);

Knob1.setLocalLookAndFeel(laf);
