# SixState Filmstrip Button

**Category:** UI

**Tags:** ScriptPanel

This creates a classic Six State filmstrip button with a ScriptPanel. Depending on the mouse-hover or mouse-pressed state the filmstrip is offset and displayed.

```javascript
Content.makeFrontInterface(500, 400);

namespace SixStateButton
{
    inline function createWidget(name, x, y)
    {
        local widget = Content.addPanel(name, x, y);

        Content.setPropertiesFromJSON(name, {
        "width": 200,
        "saveInPreset": 1,
        "allowCallbacks": "Clicks & Hover",
        "opaque": 1,
        "stepSize": "1"
        });

    	// Store variables in the panels .data object

        widget.data.hover = 0;
        widget.data.on = 0; 
        widget.data.down = 0;
        widget.data.heightPerFilmStrip = 50; 

        widget.setPaintRoutine(function(g)
        {
            var offset = this.getValue() ? 1 : 0; 
            if(this.data.down) offset += 2;
            else if(this.data.hover) offset += 4;

            g.drawImage("filmstrip",[0, 0, this.getWidth(), this.getHeight()], 
                                    0, offset * this.data.heightPerFilmstrip);
        });

        widget.setMouseCallback(function(event)
        {
            if(event.clicked) 
            {
                this.data.down = true;
                this.repaint();
            }
            else if(event.mouseUp) 
            {
                this.data.down = false;
                setButtonValue(this, 1 - this.getValue());  
                this.changed();
            }
            else 
            {
                this.data.hover = event.hover;
                this.repaint();
            }
        });

        return widget;
    };

    inline function loadFilmStrip(p, image, heightPerFilmstrip)
    {
        p.loadImage(image, "filmstrip");
        p.data.heightPerFilmstrip = heightPerFilmstrip;
    };

    inline function update(p, value)
    {
        p.setValue(value);
        p.changed();
        p.repaint();
    }

    inline function setButtonValue(p, value)
    {
        p.setValue(value);
        p.repaint();
    }
};

// Create two buttons
