// Paint Routine
WFpnl.setPaintRoutine(function(g)
{
	g.fillAll(Colours.black);
	g.setColour(Colours.lightgrey);

	p.scaleToFit(0, 0, this.getWidth(), -this.getHeight(), false); // note the minus sign to revert the path (since 0 is at the top of the panel...)

	g.fillPath(p, this.getLocalBounds(10.0));
});




// create a nice mono path
inline function updatePath()
{
	local l = data[0].length;
	local start = knbs[0].getValueNormalized() * l;			// the start sample
	local end = knbs[1].getValueNormalized() * l;			// the end sample
	local range = end-start;								// nb samples to draw
	local stride = Math.max(1, range / WFpnl.getWidth()); 	// so we draw only the necessary number of sample for the panel (imagine how the CPU will be happy for a 2 channels 10sec buffer at 96kHz...)

	local fixedFactor = 20.0; 								// a 0 to "whatever you need" value
	local vertZoom = 1.0 + knbs[2].getValueNormalized() * fixedFactor;

	local sliceBuffer;	// a buffer that will refer to the full buffer from the current start point and for the stride length so we don't lose data. Note that other methods could be used (magnitude, RMS, etc...)
	local mono;			// if the audio buffer has multiple channels, they will be summed to mono for the sake of the example

	p.clear();
	p.startNewSubPath(0, -1);	// these are fixed bounds so the waveform will stay in the centre
	p.startNewSubPath(0, 1);
	p.startNewSubPath(0, 0);

	// for a nicer look, we'll feed the path top and bottom parts separately
	// Positive part
	for (i=0; i<range; i+=stride)
	{
		mono = 0.0;

		for (ch=0; ch<data.length; ch++)
		{
			sliceBuffer = Buffer.referTo(data[ch], i+start, Math.min(stride, l - (i+start)));
			mono += sliceBuffer.getPeakRange()[1]; // take the positive value
		}

		p.lineTo(i / l, Math.max(0.0, Math.min(mono/data.length * vertZoom, 1.0)));
	}

	// Negative part (going backward)
	for (i=range-stride; i>=0; i-=stride)
	{
		mono = 0.0;

		for (ch=0; ch<data.length; ch++)
		{
			sliceBuffer = Buffer.referTo(data[ch], i+start, Math.min(stride, l - (i+start)));
			mono += sliceBuffer.getPeakRange()[0]; // take the negative value
		}

		p.lineTo(i / l, Math.min(Math.max(-1.0, mono/data.length * vertZoom), 0.0));
	}

	p.closeSubPath();
}




// update on knob change
inline function onknbsControl(component, value)
{
	// prevent start>end
	if (component == knbs[0] && value >= knbs[1].getValue()-1.0)
		knbs[1].setValue(value+1.0);
	else if (component == knbs[1] && value < knbs[0].getValue()+1.0)
		knbs[0].setValue(value-1.0);

	updatePath();
	WFpnl.repaint();
};

for (k in knbs) k.setControlCallback(onknbsControl);








