# RadioButton Panel

**Category:** UI

**Tags:** Graphics API, ScriptPanel, Simple

This example shows how to use a panel instead of multiple radio grouped buttons.

This is helpful if you want to assign the radio group to a plugin parameter so that it can be changed with a single value.

```javascript
Content.makeFrontInterface(600, 100);

namespace RadioPanel
{

inline function paintFunction(g)
{
	local idx = 0;

	for(a in this.data.areas)
	{
		g.setColour(0x22000000);

		if(idx == this.getValue())
			g.setColour(0x55FFFFFF);

		g.fillRect(a.reduced(this.data.down ? 2 : 1));

		g.setColour(Colours.withAlpha(Colours.white, this.data.hoverIndex == idx ? 0.9 : 0.6));
		g.drawAlignedText(this.data.values[idx], a, "centred");

		idx++;
	}
}	

inline function mouseCallback(event)
{
	this.data.hoverIndex = -1;
	local pos = [event.x, event.y];
	local idx = 0;

	this.data.down = event.clicked;

	if(event.hover)
	{
		for(a in this.data.areas)
		{
			if(a.contains(pos))
			{
				this.data.hoverIndex = idx;
				break;
			}

			idx++;
		}
	}

	if(event.clicked && this.data.hoverIndex != -1)
	{
		this.setValue(this.data.hoverIndex);
		this.changed();
	}

	this.repaint();
}

inline function make(name:string, values:Array)
{
	local p = Content.getComponent(name);
	p.data.values = values;

	local b = Rectangle(p.getLocalBounds(0));

	local w = b[2] / values.length;

	p.data.areas = [];

	// this is necessary for the plugin parameters to display the range correctly
	p.set("min", 0);
	p.set("max", values.length-1);
	p.set("stepSize", 1);

	for(v in p.data.values)
	{
		p.data.areas.push(b.removeFromLeft(w));
	}

	p.set("allowCallbacks", "All Callbacks");

	p.setPaintRoutine(paintFunction);
	p.setMouseCallback(mouseCallback);
}
}

RadioPanel.make("Panel1", ["Funky", "Value 2", "Something else"]);
