Panel setPaintRoutine drawing a dynamic staircase pattern driven by a knob value. StepsKnob controls both the visual step count and Bitcrusher.BitDepth attribute, with repaintImmediately in the control callback for real-time feedback.

```javascript
const var Bitcrusher = Synth.getEffect("Bitcrusher");
const var BitcrusherPanel = Content.getComponent("BitcrusherPanel");
const var StepsKnob = Content.getComponent("StepsKnob");
StepsKnob.setRange(4, 16, 1);
StepsKnob.set("stepSize", 0.1);

BitcrusherPanel.setPaintRoutine(function(g)
{
	var steps = StepsKnob.getValue(); // Get the number of steps from the knob
	var width = this.getWidth();
	var height = this.getHeight();
	var stepWidth = width / steps;
	var stepHeight = height / steps;

	g.fillAll(Colours.black);

	// Draw the staircase
	g.setColour(Colours.white);

	for (i = 0; i < steps; i++)
	{
		var x1 = i * stepWidth;
		var x2 = (i + 1) * stepWidth;
		var y = height - i * stepHeight;
		g.drawLine(x1, x2, y, y, 2); // Horizontal line

		if (i < steps - 1)
		{
			g.drawLine(x2, x2, y, height - (i + 1) * stepHeight, 2); // Vertical line
		}
	}
});

// Repaint the panel based on Knob value, attach it to the FX
inline function onStepsKnobControl(component, value)
{
	BitcrusherPanel.repaintImmediately();
	Bitcrusher.setAttribute(Bitcrusher.BitDepth, value);
};

Content.getComponent("StepsKnob").setControlCallback(onStepsKnobControl);
```

# LayoutBuilder Dynamic UI Factory

**Source:** [Forum Topic](https://forum.hise.audio/topic/11321)

**Tags:** Scripting, expert

Recursive stack-based component builder that processes a JSON tree of component definitions. Uses Content.addKnob/addButton/addPanel etc. to create components dynamically and applies all properties from the JSON, enabling portable UI layouts between projects.

```javascript
/*
* Author: David Healey
* License: CC0
* Last updated: 08/12/2024
*/

namespace LayoutBuilder
{
const data = [];

inline function add(arr: Array)
{
	data.concat(arr);
}

inline function process()
{
	local stack = data.clone();

	while (stack.length > 0)
	{
		//local node = stack.shift();
		local node = stack.pop();

		if (!isDefined(node.type) || !isDefined(node.id))
			continue;

		addComponent(node.id, node);

		if (!isDefined(node.childComponents))
			continue;

		for (x in node.childComponents)
			x.parentComponent = node.id;

		for (i = node.childComponents.length - 1; i >= 0; i--)
			stack.push(node.childComponents[i]);

		//stack.concat(node.childComponents);
	}
}

inline function:
object addComponent(id: string, properties: JSON)
{
	local c = Content.getComponent(id);

	if (!isDefined(c))
	{
		local type = properties.type.replace("Scripted").replace("Script");

		switch (type)
		{
		case "Slider":
			c = Content.addKnob(id, properties.x, properties.y);
			break;

		case "Button":
			c = Content.addButton(id, properties.x, properties.y);
			break;

		case "Table":
			c = Content.addTable(id, properties.x, properties.y);
			break;

		case "ComboBox":
			c = Content.addComboBox(id, properties.x, properties.y);
			break;

		case "Label":
			c = Content.addLabel(id, properties.x, properties.y);
			break;

		case "Image":
			c = Content.addImage(id, properties.x, properties.y);
			break;

		case "Viewport":
			c = Content.addViewport(id, properties.x, properties.y);
			break;

		case "Panel":
			c = Content.addPanel(id, properties.x, properties.y);
			break;

		case "AudioWaveform":
			c = Content.addAudioWaveform(id, properties.x, properties.y);
			break;

		case "SliderPack":
			c = Content.addSliderPack(id, properties.x, properties.y);
			break;

		case "WebView":
			c = Content.addWebView(id, properties.x, properties.y);
			break;

		case "FloatingTile":
			c = Content.addFloatingTile(id, properties.x, properties.y);
			break;
		}
	}

	local allProperties = c.getAllProperties();

	for (x in properties)
	{
		if (!allProperties.contains(x) || ["id"].contains(x))
			continue;

		c.set(x, properties[x]);
	}

	return c;
}
}
```

