# Bipolar Pan Slider LAF

**Source:** [Forum Topic](https://forum.hise.audio/topic/11641)

**Tags:** General Questions, trusted

drawLinearSlider LAF with bipolar fill rendering from center point for a pan-style slider. Calculates fill direction based on whether value is left or right of center, with a draggable handle showing the numeric display value.

```javascript
Content.makeFrontInterface(450, 100);

const var SLIDER = Content.getComponent("SLIDER");
const var knblaf = Content.createLocalLookAndFeel();

knblaf.registerFunction("drawLinearSlider", function(g, obj)
{
	var a = obj.area;
	var handle = a[2] / 6;
	var mid = a[2] / 2;
	var n = (a[2] - handle) / a[2];

	var bipolarValue = obj.valueNormalized * 2 - 1;
	var v = mid + (bipolarValue * mid * n);

	g.setColour(Colours.black);
	g.fillRoundedRectangle(a, a[3] * 0.5);

	if (bipolarValue >= 0)
	{
		g.setColour(Colours.lightgrey);
		g.fillRoundedRectangle([mid, 0, v - mid, a[3]], a[3] * 0.5);
	}

	else
	{
		g.setColour(Colours.lightgrey);
		g.fillRoundedRectangle([v, 0, mid - v, a[3]], a[3] * 0.5);
	}

	g.setColour(Colours.whitesmoke);
	g.fillRoundedRectangle([v - handle / 2, 0, handle, a[3]], a[3] * 0.5);

	g.setColour(Colours.black);
	var displayValue = Math.round(bipolarValue * 100);
	g.drawAlignedText(Engine.doubleToString(displayValue, 0), [v - handle / 2, 0, handle, a[3]], "centred");
