# SNEX Waveshaper with Dry/Wet Mix

**Source:** [Forum Topic](https://forum.hise.audio/topic/6872)

**Tags:** General Questions, trusted

SNEX shaper node template with a parameterized dry/wet mix control. Implements an exponential waveshaper transfer function and blends the processed signal with the clean input using a Mix parameter routed via setParameter.

```javascript
template <int NumVoices> struct snex_shaper
{
	SNEX_NODE(snex_shaper);

	float Mix = 0.0f;
	float a = 0.0f;

	float getSample(float input)
	{
		//Store the clean input
		a = input;

		//Waveshaper Transfer Function
		input = 9.5 * (1.0 - 1.0 / Math.exp(input));

		//Apply Mix Knob to blend Distorted & Clean Signal together
		return input * (1.0 - Mix) + a * Mix;
	}

	template <typename T> void process(T& data)
	{
		for(auto ch : data)
		{
			for(auto& s : data.toChannelData(ch))
				s = getSample(s);
		}
	}

	template <typename T> void processFrame(T& data)
	{
		for(auto& s : data)
			s = getSample(s);
	}

	void reset()
	{

	}

	void prepare(PrepareSpecs ps)
	{

	}

	void setExternalData(const ExternalData& d, int index)
	{
	}

	template <int P> void setParameter(double v)
	{
		if (P == 0)
			Mix = (float)v;

	}
};
