# Rotary Slider LAF with Arc and Line Indicator

**Source:** [Forum Topic](https://forum.hise.audio/topic/3630)

**Tags:** General Questions, author

laf.registerFunction("drawRotarySlider") with Content.createPath, g.drawPath, and g.rotate to draw a custom rotary knob with arc track and rotating line indicator. Calculates arc position from value range and renders with configurable stroke and indentation.

```javascript
const var laf = Content.createLocalLookAndFeel();

laf.registerFunction("drawRotarySlider", function(g, obj)
{
	var a = obj.area;
	var width = a[2];
	var height = a[3];
	var stroke = 3;
	var range = obj.max - obj.min;
	var startOffset = Math.PI * 0.25;
	var fullArc = Math.PI * 1.5;
	var arcPos = startOffset + fullArc * (obj.value - obj.min) / range;
	var intend = width * 0.25;

	g.setColour(obj.itemColour1);
	g.fillEllipse(a);
	g.setColour(obj.itemColour2);
	g.drawEllipse([stroke / 2, stroke / 2, width - stroke, height - stroke], stroke);

	var p = Content.createPath();
	p.addArc([0, 0, 1.0, 1.0], Math.PI + startOffset + fullArc, Math.PI + startOffset);

	g.setColour(0x22FFFFFF);

	var magicScaler = 1.4;
	g.drawPath(p, [
	               intend / 2 + stroke,
	               intend / 2 + stroke,
	               width - intend - 2 * stroke,
	               height - magicScaler * intend - 2 * stroke
	           ], intend);

	g.rotate(arcPos, [a[2] / 2, a[3] / 2]);
	g.setColour(obj.textColour);
	g.drawLine(width / 2, height / 2, intend - stroke + width / 2, height - stroke, 4.0);
});

