		else if (u.picture.charAt(0) == 'h')
		{
			var ext = u.picture.split(".");
			ext = ext[ext.length - 1];

			var url = u.picture.substring(0, u.picture.lastIndexOf("/") + 1);
			var subUrl = u.picture.replace(url, "");

			Server.setBaseURL(url);
			Server.downloadFile(subUrl, {}, userThumbnailFolder.getChildFile(u.username + "." + ext), function(info) {});
		}
	}
});
