Content.createLocalLookAndFeel with drawRotarySlider to draw a rotary knob using three overlapping arcs — background, value, and pointer. Uses Content.createPath with addArc and Rectangle helper for precise arc geometry and configurable thickness.

```javascript
Content.makeFrontInterface(600, 600);
Console.clear();


const var knobArc_LAF = Content.createLocalLookAndFeel();

knobArc_LAF.registerFunction("drawRotarySlider", function(g, obj)
{
	g.setColour(obj.bgColour);
	g.fillEllipse(obj.area);

	var mainArc1 = Content.createPath();
	var pointerArc = Content.createPath();
	var mainArc2 = Content.createPath();

	var rect	= Rectangle(obj.area);
	var thickness	= obj.area[2] / 20;
	var arcLength	= Math.PI / 10.0; 			// length of the arc (in radian)
	var start	= -3 * Math.PI / 4;				// the starting point of the knob
	var amplitude	= 3 * Math.PI / 2;				// the full coverage of the knob
	var end	= start + amplitude * obj.valueNormalized;

	mainArc1.addArc(rect.reduced(thickness * 0.5), start, end);
	pointerArc.addArc(rect.reduced(thickness * 1.5), end - arcLength / 2.0, end + arcLength / 2.0);
	mainArc2.addArc(rect.reduced(thickness * 2.5), start, end);

	g.setColour(obj.itemColour1);
	g.drawPath(mainArc1, mainArc1.getBounds(1.0), thickness);
	g.setColour(obj.textColour);
	g.drawPath(pointerArc, pointerArc.getBounds(1.0), thickness);
	g.setColour(obj.itemColour2);
	g.drawPath(mainArc2, mainArc2.getBounds(1.0), thickness);
});

Content.getComponent("Knob1").setLocalLookAndFeel(knobArc_LAF);
