# Component Position Tracker with Broadcaster

**Source:** [Forum Topic](https://forum.hise.audio/topic/11357)

**Tags:** Scripting, trusted

Engine.createBroadcaster with attachToComponentMouseEvents and Content.getComponentUnderMouse to track hovered components. Recursively walks the parentComponent chain to compute absolute screen position, displaying the tooltip and coordinates on a panel.

```javascript
Content.makeFrontInterface(600, 600);

const AllComponents = Content.getAllComponents("");

// Broadcaster definition
const var getHoveredComponentBC = Engine.createBroadcaster(
{
"id": "getHoveredComponentBC",
"args": ["component", "event"],
"tags": []
});

// attach to event Type
getHoveredComponentBC.attachToComponentMouseEvents(AllComponents, "All Callbacks", "");


getHoveredComponentBC.addListener(AllComponents, "get position", function(component, event)
{
	if (event.hover)
	{
		var comp;

		for (c in AllComponents)
			if (c.get("id") == Content.getComponentUnderMouse())
			{
				comp = c;
				break;
			}

		if (isDefined(comp))
		{
			TooltipPanel.data.tooltip = comp.get("tooltip") + " || pos: " + trace(getPositionOfComponent(comp));
			TooltipPanel.repaint();
		}
	}
});


inline function getPositionOfComponent(component)
{
	local pos = {"x": component.get("x"), "y": component.get("y")};

	local comp = component;

	//	check if component has parent and grandparents
	for (i = 0; comp.get("parentComponent") != ""; i++)
	{
		comp = getComponent(comp.get("parentComponent"));
		local p = getParentPosition(comp);
		pos.x += p.x;
		pos.y += p.y;
	}

	return pos;
};

//	get the parent position
inline function getParentPosition(parent)
{
	return {"x": parent.get("x"), "y": parent.get("y")};
};

//	get the component object
inline function getComponent(componentId)
{
	for (c in AllComponents)
		if (c.get("id") == componentId)
		{
			return c;
			break;
		}
}

const TooltipPanel = Content.getComponent("TooltipPanel");

TooltipPanel.setPaintRoutine(function(g)
{
	g.setColour(Colours.white);
	g.setFont("default", 16);

	if (isDefined(this.data.tooltip))
		g.drawAlignedText(this.data.tooltip, this.getLocalBounds(0), "centred");
});
```

# HSL Colour Palette Generator

**Source:** [Forum Topic](https://forum.hise.audio/topic/11334)

**Tags:** Scripting, expert

Colours.toHsl and Colours.fromHsl with typed inline functions to generate a 10-shade colour palette from a base colour. Includes hue shifting, parabolic saturation curves, and automatic text colour contrast based on background luminance. Uses panel bgColour property as the palette seed.

```javascript
Content.makeFrontInterface(600, 600);

const var Panel1 = Content.getComponent("Panel1");

Panel1.setPaintRoutine(function(g)
{
	var a = this.getLocalBounds(0);
	var w = a[2] / 10;
	var labels = [900, 800, 700, 600, 500, 400, 300, 200, 100, 50];
	var palette = generatePalette(this.get("bgColour"));

	for (i = 0; i < palette.length; i++)
	{
		g.setColour(palette[i]);
		g.fillRect([w * i, a[1], w, w]);

		g.setColour(Colours.white);
		g.setFont("Oxygen", 12);
		g.drawAlignedText(labels[i], [w * i, w, w, w], "centred");
	}
});

const var Panel2 = Content.getComponent("Panel2");

Panel2.setPaintRoutine(function(g)
{
	var a = this.getLocalBounds(0);

	g.fillAll(this.get("bgColour"));

	g.setColour(getTextColour(this.get("textColour"), this.get("bgColour"), 0.5));
	g.drawAlignedText("This is some text", a, "centred");
});

const var Panel3 = Content.getComponent("Panel3");

Panel3.setPaintRoutine(function(g)
{
	var a = this.getLocalBounds(0);

	g.fillAll(this.get("bgColour"));

	g.setColour(getTextColour(this.get("textColour"), this.get("bgColour"), 0.5));
	g.drawAlignedText("This is some text", a, "centred");
});

//! Functions
inline function:
Colour getTextColour(baseColour: Colour, backgroundColour: Colour, shadeIndex: number)
{
	local bc = Colours.toHsl(backgroundColour);
	local c = Colours.toHsl(baseColour);

	c[0] = getShiftedHue(c[0], shadeIndex, 4);
	c[1] = getShiftedSaturation(shadeIndex, c[1], 0.5);
	c[2] = 1 - bc[2];

	return Colours.fromHsl(c);
}

inline function:
Array generatePalette(baseColour: Colour)
{
	local result = [];

	for (i = 0; i < 10; i++)
	{
		local c = Colours.toHsl(baseColour);

		c[0] = getShiftedHue(c[0], i / 10, 4);
		c[1] = getShiftedSaturation(i / 10, c[1], 0.5);
		c[2] = (i + 1) / 10;

		result.push(Colours.fromHsl(c));
	}

	return result;
}

inline function:
number getShiftedHue(baseHue: number, index: number, maxShift: number)
{
	return baseHue + maxShift * index / 360;
}

inline function:
number getShiftedSaturation(index: number, maxSaturation: number, steepness: number)
{
	local x = index;
	local a = maxSaturation * steepness;
	local b = maxSaturation;
	local saturation = -4 * a * Math.pow((x - 0.5), 2) + b;

	return Math.max(0.0, Math.min(1.0, saturation));
}
```

