{
	//	switch between external clock (daw) and internal clock
	//	daw playing - TH will sync to that, will get beat and position
	//	daw stops - the internal clock continue to tick from where the
	//	daw stopped
	//	daw start play - clock will sync back to the daws playhead
	TH.setSyncMode(isPlaying ? TH.PreferExternal : TH.SyncInternal);
