# Panel-Based ComboBox with Mutual Exclusion

**Source:** [Forum Topic](https://forum.hise.audio/topic/9346)

**Tags:** Scripting, trusted, solved

Panel popupMenuItems property with setPaintRoutine and setMouseCallback to create combo box behavior on panels. Implements mutual exclusion between two panel combo boxes using ~~ markup for disabled items in the popupMenuItems string. Uses selectedPopupIndex and event.result for popup menu handling.

```javascript
Content.makeFrontInterface(200, 100);

const CmbPnls = Content.getAllComponents("CmbPnl");
const var cmbItems = ["Item1", "Item2", "Item3", "Item4", "Item5", "Item6"];

for (cmb in CmbPnls)
	cmb.set("popupMenuItems", cmbItems.join("\n"));

//	paint routine
const PR = function(g)
{
	var a = this.getLocalBounds(0);

	g.setColour(this.get("bgColour"));
	g.fillRoundedRectangle(a, 2);

	g.setColour(this.get("textColour"));
	g.drawAlignedText(this.get("popupMenuItems").split("\n")[this.getValue()], a, "centred");
};

//	mouse callback
const MCB = function(event)
{
	if (event.result)
	{
		this.setValue(event.result - 1);
		this.changed();
	}
};

//	control callback
inline function onCmbPnlsControl(component, value)
{
	local theotherlist = [];

	for (item in cmbItems)
		if (item == component.get("popupMenuItems").split("\n")[value])
			theotherlist.push("~~" + item + "~~");

		else
			theotherlist.push(item);

	CmbPnls[!CmbPnls.indexOf(component)].set("popupMenuItems", theotherlist.join("\n"));
	component.set("selectedPopupIndex", value);
};

for (cmb in CmbPnls)
{
	cmb.setPaintRoutine(PR);
	cmb.setMouseCallback(MCB);
	cmb.setControlCallback(onCmbPnlsControl);
