```javascript
Content.makeFrontInterface(600, 600);


//some useful functions

inline function escapeString(str)
{
	local obj = {};
	obj.s = str;

	return trace(obj.s); // let HISE do the escaping for us
}

inline function deescapeString(str)
{
	// De-escape double quotes
	while(str.contains('\\"'))
		str = str.replace('\\"', '"');

	// De-escape newlines
	while(str.contains('\\n'))
		str = str.replace('\\n', '\n');

	return str;
}

// we gotta send something right?
const var p =
{
	"first_argument": 69
};

// we'll store the function from the server into this variable.
// as much as it would be cool to execute it directly in the server callback, I did not have success with it.
// eval inside the server callback does not work, even if called with delay
var f = 0;
Server.setBaseURL("https://pastebin.com/raw/"); // because if we don't use this method, HISE prepends / to the link in callwithPOST and the call doesn't go through
Server.callWithGET("JfrhjGmL", p, function(status, response)
{
	if (status == 200)
	{
		f = response.func; // save our code string here, to be evaluated later
		Console.print("Function: " + response.func);
	}
});

// Time to make some controls!

const var button = Content.addButton("Play_A_Note", 230, 200);
button.setValue(false); //reset on init as the callback only triggers on true

