// as it was pulled from the server
inline function onPlay_A_NoteControl(component, value)
{
	if (value)
	{
		eval(f); // the secret sauce - this evaluates the string as raw code and attempts to execute it
		component.setValue(0);
	}
};

Content.getComponent("Play_A_Note").setControlCallback(onPlay_A_NoteControl);


const var button2 = Content.addButton("Knob1_To_Max", 230, 100);
button.setValue(false);

