// so that it looks like "Knob1.setValue(Knob1.get(\"max\"));"
// use the escapeString(str) for that or do it natively in your framework on your server if it has the function

Server.setBaseURL("https://pastebin.com/raw/");
Server.callWithGET("Msqgvvk5", p, function(status, response)
{
	if (status == 200)
	{
		f2 = response.func;
		Console.print("Function: " + response.func);
	}
});

inline function onKnob1ToMaxControl(component, value)
