# Horizontal Linear Slider LAF with Bidirectional

**Source:** [Forum Topic](https://forum.hise.audio/topic/8340)

**Tags:** Scripting, trusted

Content.createLocalLookAndFeel with drawLinearSlider to render a horizontal slider with bidirectional support. Detects bidirectional mode from min/max symmetry and adjusts the fill area to draw from center when active.

```javascript
Content.makeFrontInterface(600, 600);

const horizontalSlider = Content.createLocalLookAndFeel();

horizontalSlider.registerFunction("drawLinearSlider", function(g, obj)
{
	var a = obj.area;
	var isBidirectional = -1.0 * obj.min == obj.max;

	g.setColour(obj.bgColour);
	g.fillRoundedRectangle(a, 8);

	g.setColour(Colours.withAlpha(obj.itemColour1, obj.enabled ? 1.0 : 0.5));
	g.fillRoundedRectangle([12, a[3] / 2 - 3 / 2, a[2] - 24, 3], 2);

	g.setColour(Colours.withAlpha(obj.itemColour2, obj.enabled ? 1.0 : 0.5));

	var centerX = a[2] / 2;
	var fillWidth;
	var startX = 12;

	if (isBidirectional)
	{
		if (obj.valueNormalized > 0.5)
		{
			startX = centerX;
			fillWidth = ((a[2] - 12) * obj.valueNormalized) - centerX;
		}

		else
		{
			fillWidth = centerX * (1.0 - obj.valueNormalized * 2);
			startX = centerX - fillWidth;

			fillWidth = Math.min(fillWidth, centerX - 12);
			startX = Math.max(startX, 12);
		}

		g.fillRoundedRectangle([startX, a[3] / 2 - 3 / 2, fillWidth, 3], 2);
	}

	else
	{
		fillWidth = (a[2] - 24) * obj.valueNormalized;
		g.fillRoundedRectangle([12, a[3] / 2 - 3 / 2, fillWidth, 3], 2);
	}

	var w = a[2] * 0.2;
	var x = a[2] * obj.valueNormalized - (w + 4) * obj.valueNormalized + 2;

	g.setColour(Colours.grey);
	g.fillRoundedRectangle([x + 1, a[3] / 2 - (a[3] - 4) / 2, w - 2, a[3] - 4], 8);
});


const var Knob1 = Content.getComponent("Knob1");
Knob1.setLocalLookAndFeel(horizontalSlider);

const var Knob2 = Content.getComponent("Knob2");
Knob2.setLocalLookAndFeel(horizontalSlider);
