# Ellipse Hit Detection with Math

**Source:** [Forum Topic](https://forum.hise.audio/topic/7986)

**Tags:** Scripting, trusted

Panel setMouseCallback with the ellipse containment formula (normalized distance from center) to detect if the mouse is inside a drawn ellipse. Stores the ellipse area in panel data during the paint routine for use in the mouse callback.

```javascript
Content.makeFrontInterface(600, 600);
const var Pnl = Content.getComponent("Pnl");

Pnl.setPaintRoutine(function(g)
{
	var a = this.getLocalBounds(0);

	this.data.areas = {};
	var areas = this.data.areas;

	g.fillAll("0x33ffffff");

	areas.ellipse = [10, 20, a[2] - 20, a[3] - 40];
	g.setColour(Colours.chartreuse);
	g.fillEllipse(areas.ellipse);
});

Pnl.setMouseCallback(function(event)
{
	if (event.hover)
	{
		var result = whichEllipse(this.data.areas, {"x": event.x, "y": event.y});

		if (isDefined(result))
			Console.print(result);
	}
});


inline function whichEllipse(areas, mouse)
{
	for (a in areas)
	{
		local obj = areas[a];

		local rx = obj[2] / 2;
		local ry = obj[3] / 2;
		local cx = obj[0] + rx;
		local cy = obj[1] + ry;

		local distance = Math.pow(mouse.x - cx, 2) / Math.pow(rx, 2) + Math.pow(mouse.y - cy, 2) / Math.pow(ry, 2);

		if (distance <= 1)
			return a;

		else
			Console.print("outside");
	}
};
```

# Multi-Shape Hit Detection with Hover

**Source:** [Forum Topic](https://forum.hise.audio/topic/7986)

**Tags:** Scripting, trusted

Panel setPaintRoutine and setMouseCallback to detect mouse hover over ellipses, rectangles, and triangles drawn on a single panel. Each shape is stored as a typed object in panel data with its area, and a generic hit-test function checks containment based on shape type. Hover state changes the fill alpha for visual feedback.

```javascript
Content.makeFrontInterface(600, 600);
const var Pnl = Content.getComponent("Pnl");

Pnl.setPaintRoutine(function(g)
{
	var a = this.getLocalBounds(0);

	this.data.areas = {};
	var areas = this.data.areas;

	g.fillAll("0x33ffffff");

	var hovered = isDefined(this.data.hovered) ? this.data.hovered : [];

	areas.ellipse1 = {"area": [10, 50, 140, 100], "type": "ellipse"};
	g.setColour(Colours.withAlpha(Colours.chartreuse, hovered.contains("ellipse1") ? 1.0 : 0.5));
	g.fillEllipse(areas.ellipse1.area);

	areas.ellipse2 = {"area": [20, 100, 100, 60], "type": "ellipse"};
	g.setColour(Colours.withAlpha(Colours.red, hovered.contains("ellipse2") ? 1.0 : 0.5));
	g.fillEllipse(areas.ellipse2.area);

	areas.rect1 = {"area": [100, 310, 200, 50], "type": "rectangle"};
	g.setColour(Colours.withAlpha(Colours.cadetblue, hovered.contains("rect1") ? 1.0 : 0.5));
	g.fillRoundedRectangle(areas.rect1.area, 2);

	areas.rect2 = {"area": [50, 30, 70, 140], "type": "rectangle"};
	g.setColour(Colours.withAlpha(Colours.orange, hovered.contains("rect2") ? 1.0 : 0.5));
	g.fillRoundedRectangle(areas.rect2.area, 2);

	areas.triangle1 = {"area": [70, 120, 100, 70], "type": "triangle", "radian": Math.PI * 2};
	g.setColour(Colours.withAlpha(Colours.green, hovered.contains("triangle1") ? 1.0 : 0.5));
	g.fillTriangle(areas.triangle1.area, areas.triangle1.radian);

	areas.triangle2 = {"area": [170, 120, 100, 70], "type": "triangle", "radian": Math.PI * 0.4};
	g.setColour(Colours.withAlpha(Colours.yellow, hovered.contains("triangle2") ? 1.0 : 0.5));
	g.fillTriangle(areas.triangle2.area, areas.triangle2.radian);

	g.setFont("default", 14);
	areas.text1 = {"area": [10, 300, a[2] - 20, 30], "type": "text"};
	g.setColour(Colours.withAlpha(Colours.chartreuse, hovered.contains("text1") ? 1.0 : 0.5));
	g.drawAlignedText("kåldolmar och kalsipper med Nationalteatern", areas.text1.area, "centred");
});

Pnl.setMouseCallback(function(event)
{
	if (event.hover)
	{
		var result = whichArea(this.data.areas, {"x": event.x, "y": event.y});

		if (isDefined(result) && result.length)
			this.data.hovered = result;

		else
			this.data.hovered = [];

		this.repaint();
	}
});


inline function whichArea(areas, mouse)
{
	local result = [];

	for (i in areas)
	{
		local a = areas[i].area;

		switch (areas[i].type)
		{
		case "ellipse":
			local rx = a[2] / 2;
			local ry = a[3] / 2;
			local cx = a[0] + rx;
			local cy = a[1] + ry;

			local distance = Math.pow(mouse.x - cx, 2) / Math.pow(rx, 2) + Math.pow(mouse.y - cy, 2) / Math.pow(ry, 2);

			if (distance <= 1)
				result.push(i);

			break;

		case "rectangle":
			if (mouse.x >= a[0] && mouse.x <= a[0] + a[2] && mouse.y >= a[1] && mouse.y <= a[1] + a[3])
				result.push(i);

			break;

		// Here I should have a case for "triangle", but I couldn't figure out
		// How to do it :)
		// So instead the triangles will go in default case, just like the
		// rectangles
		default:
			if (mouse.x >= a[0] && mouse.x <= a[0] + a[2] && mouse.y >= a[1] && mouse.y <= a[1] + a[3])
				result.push(i);

			break;
		}
	}

	return result;
};
```

