# Animated Text Along a Path

**Source:** [Forum Topic](https://forum.hise.audio/topic/7986)

**Tags:** Scripting, trusted

Content.createPath with getPointOnPath and getLength to position individual characters along an ellipse and star path. Uses Math.atan for character rotation and setTimerCallback for continuous scrolling animation. Demonstrates per-character rendering with g.rotate and g.drawAlignedText at path-derived coordinates.

```javascript
Content.makeFrontInterface(600, 600);
Console.clear();

const var Pnl = Content.getComponent("Pnl");
Pnl.data.angle = 0;

const var p = Content.createPath();

const var text =
    "Yeahhh!!! Writing on a path is possible thanks to our friend Pythagoras the greatest mathematician of all time!";
const var charSize = 12;
const var charSpace = 8;
const var speed = 1;

Pnl.setPaintRoutine(function(g)
{
	p.clear();
	p.addEllipse([100, 200, 400, 200]);
	p.addStar([300, 300], 5, 100, 200, Math.toRadians(this.data.angle) * -1);

	g.setColour(Colours.white);
	g.drawPath(p, p.getBounds(1.0), 0.2);

	for (i = 0; i < text.length; i++)
	{
		var point = p.getPointOnPath((i * charSpace + (p.getLength() / 360 * this.data.angle)) % p.getLength());

		var next = p.getPointOnPath(((i + 1) * charSpace + (p.getLength() / 360 * this.data.angle)) % p.getLength());

		var adj = next[0] - point[0];
		var opp = next[1] - point[1];

		var a = Math.atan(opp / adj);

		if (adj < 0)
			a += Math.PI;

		g.rotate(a, point);
		g.drawAlignedText(text.charAt(i), [point[0] - charSize / 2, point[1] - charSize, charSize, charSize], "centred");
		g.rotate(-a, point);
	}
});


Pnl.setTimerCallback(function()
{
	this.data.angle = (this.data.angle + speed) % 360;
	this.repaint();
});

Pnl.startTimer(30);
```

