# Custom Scrollable List with Keyboard Navigation

**Source:** [Forum Topic](https://forum.hise.audio/topic/7505)

**Tags:** Scripting, trusted

Panel inside a Viewport with setPaintRoutine to render a scrollable item list with selection, hover highlighting, and rounded rectangle rows. Implements setKeyPressCallback for up/down arrow navigation with automatic scroll-into-view using Viewport.setScrollPosition. Includes setMouseCallback for click selection and hover detection.

```javascript
Content.makeFrontInterface(600, 600);

const ROW_HEIGHT = 38;
const ROW_SPACE = 7;

const list = ["Item 1", "Item 2", "Item 3", "Item 4", "Item 5", "Item 6", "Item 7", "Item 8", "Item 9", "Item 10",
              "Item 11", "Item 12", "Item 13", "Item 14", "Item 15"];

const var Viewport1 = Content.getComponent("Viewport1");
const var Viewport2 = Content.getComponent("Viewport2");

const var ScriptPanel1 = Content.getComponent("ScriptPanel1");
ScriptPanel1.data.items = list;
ScriptPanel1.set("height", list.length * (ROW_HEIGHT + ROW_SPACE) - ROW_SPACE);


ScriptPanel1.setPaintRoutine(function(g)
{
	var a = this.getLocalBounds(0);
	var radius = this.get("borderRadius");

	for (i = 0; i < this.data.items.length; i++)
	{
		var a = [0, i * (ROW_HEIGHT + ROW_SPACE), this.getWidth(), ROW_HEIGHT];

		if (this.getValue() == i)
			g.setColour(this.get("itemColour"));

		else
			g.setColour(Colours.withAlpha(this.get("bgColour"), this.data.hover == i ? 1.0 : 0.6));

		g.fillRoundedRectangle(a, radius);

		if (this.getValue() == i)
		{
			g.setColour(this.get("itemColour2"));
			g.fillRoundedRectangle([a[0], a[1], 5, a[3]], {CornerSize: radius, Rounded: [1, 0, 1, 0]});
		}

		g.setColour(Colours.withAlpha(this.get("textColour"), this.getValue() == i ? 1.0 : 0.7));

		// Item name
		var text = this.data.items[i];
		g.drawAlignedText(text, [a[0] + 10, a[1] - 0.5, a[2], a[3]], "left");
	}
});

ScriptPanel1.setConsumedKeyPresses(["space", "left", "right", "up", "down"]);

ScriptPanel1.setKeyPressCallback(function(event)
{
	var newValue = this.getValue();

	if (event.description == "cursor up")
	{
		if (this.getValue() > 0)
			newValue--;
	}

	else if (event.description == "cursor down")
	{
		var numItems = this.data.items.length;

		if (this.getValue() < numItems - 1)
			newValue++;
	}

	if (newValue != this.getValue())
	{
		this.setValue(newValue);
		scrollVP(newValue);
		this.changed();
	}

	return true;
});

ScriptPanel1.setMouseCallback(function(event)
{
	var items = this.data.items;
	var value = Math.floor(event.y / this.getHeight() * items.length);

	this.data.hover = event.hover ? items[value] : -1;

	if (event.clicked)
	{
		this.setValue(value);
		this.changed();
	}

	else
		this.repaint();
});


// SCROLLER
//const var diffHeight = ScriptPanel1.getHeight() - Viewport1.getHeight();


inline function scrollVP(idx)
{
	local visibleItemsFloat = ScriptPanel1.getHeight() / Viewport1.getHeight();

	// viewPositionY trucate to 0-1 so wee need a larger range to make it "stick"
	local lowY = 0 - (visibleItemsFloat / list.length); // below 0 limit
	local topY = 1 + (visibleItemsFloat / list.length); // above 1 limit

	local posY = remap(0, list.length - 1, lowY, topY, idx);

	Viewport1.set("viewPositionY", posY);
}


inline function lerp(a, b, t)
{
	return a * (1.0 - t) + b * t;
}

inline function invLerp(c, d, v)
{
	return (v - c) / (d - c);
}

inline function remap(inMin, inMax, outMin, outMax, value)
{
	local t = invLerp(inMin, inMax, value);
	return lerp(outMin, outMax, t);
}
```

# Increment/Decrement Button Pairs for Labels

**Source:** [Forum Topic](https://forum.hise.audio/topic/7736)

**Tags:** Scripting, trusted

Paired increment/decrement buttons mapped to label components using indexOf and Math.floor for index derivation. Uses modulo to determine direction from the button index and parseInt on the label text for numeric value tracking.

```javascript
Content.makeFrontInterface(600, 600);
Console.clear();

const var lbls = [Content.getComponent("Label1"),
                  Content.getComponent("Label2"),
                  Content.getComponent("Label3"),
                  Content.getComponent("Label4"),
                  Content.getComponent("Label5"),
                  Content.getComponent("Label6")];

const var btns = [Content.getComponent("decBtn0"),
                  Content.getComponent("incBtn0"),
                  Content.getComponent("decBtn1"),
                  Content.getComponent("incBtn1"),
                  Content.getComponent("decBtn2"),
                  Content.getComponent("incBtn2"),
                  Content.getComponent("decBtn3"),
                  Content.getComponent("incBtn3"),
                  Content.getComponent("decBtn4"),
                  Content.getComponent("incBtn4"),
                  Content.getComponent("decBtn5"),
                  Content.getComponent("incBtn5")];


const var values = [];


// lbls can be used to recall the values
inline function onlblsControl(component, value)
{
	values[lbls.indexOf(component)] = parseInt(component.get("text"));
};

for (l in lbls)
	l.setControlCallback(onlblsControl);


inline function onbtnsControl(component, value)
{
	if (value)
	{
		// lblIdx can be used to set the corresponding attribute
		local btnIdx = btns.indexOf(component);
		local lblIdx = Math.floor(btnIdx / 2);

		// even is dec, odd is inc
		local decOrInc = (btnIdx % 2 == 0) ? -1 : 1;

		// Define different limits for top and bottom rows
		local loLimit = lblIdx < 3 ? 10 : 0;
		local hiLimit = lblIdx < 3 ? 20 : 50;

		// Here set your module's parameter
		values[lblIdx] = Math.round(Math.range(values[lblIdx] + decOrInc, loLimit, hiLimit));

		// Reflect on the label
		lbls[lblIdx].set("text", values[lblIdx]);
	}
}

for (b in btns)
	b.setControlCallback(onbtnsControl);
