# Tooltip Panel with Mouse Tracking

**Source:** [Forum Topic](https://forum.hise.audio/topic/7561)

**Tags:** Scripting, trusted, solved

Content.getAllComponents with a full-screen transparent panel and setMouseCallback to track which component the mouse is hovering over. Compares mouse coordinates against stored component areas to identify the hovered component, displays its tooltip text, and temporarily disables the tracking panel to allow mouse interaction with the underlying component.

```javascript
Content.makeFrontInterface(600, 600);

// GET ALL COMPONENTS
const AllComponents = Content.getAllComponents("");

//	REFERENCE TO DISPLAY TOOLTIP PANEL
const var TooltipPnl = Content.getComponent("TooltipPnl");

//	TOOLTIP PR	----------------------------
TooltipPnl.setPaintRoutine(function(g)
{
	g.setColour(Colours.white);

	if (this.data.id != "")
	{
		var c = Content.getComponent(this.data.id);
		var text = c.get("tooltip");

		if (!c.get("enabled"))
			text += " (disabled)";

		g.drawAlignedText(text, this.getLocalBounds(0), "left");
	}

});


//	GET AREA & ID FROM ALL COMPONENTS EXCEPT THE PANEL THAT IS ON TOP OVER ALL
reg CompsInfo = [];

inline function getCoordinates()
{
	for (c in AllComponents)
	{
		if (c.get("id") != "MousePanel")
		{
			local obj =
			{
"id":
				c.get("id"),
"area":
				[c.get("x"), c.get("y"), c.getWidth(), c.getHeight()]
			};

			CompsInfo.push(obj);
		}
	}
}

//	Execute
getCoordinates();

//	REGISTER A CURRENT HOVERED COMPONENT
reg currentComp;

//	THE PANEL THAT IS ON TOP OVER ALL COMPONENTS, AND TRACK THE MOUSE POSITION
const var MousePanel = Content.getComponent("MousePanel");
MousePanel.setMouseCallback(function(event)
{
	//	CALL FUNCTION TO GET WHICH COMPONENT IS HOVERED
	var c = whichComp(CompsInfo, [event.x, event.y]);

	if (isDefined(c))
	{
		TooltipPnl.data.id = c.id;
		currentComp = c.id;
		TooltipPnl.repaint();

		//	IF HOVERED COMPONENT IS ENABLED, DISABLE MOUSEPANEL
		//	AND START TIMER THAT WILL CHECK IF THE MOUSE IS STILL OVER
		//	AN ENABLED COMPONENT, IF NOT, THE MOUSEPANEL WILL BE ENABLED AGAIN
		if (Content.getComponent(c.id).get("enabled"))
		{
			this.set("enabled", false);
			t.startTimer(100);
		}
	}

	else
	{
		TooltipPnl.data.id = "";
		TooltipPnl.repaint();
	}
});

//	TIMER CHECKING IF MOUSE IS OVER ENABLED COMPONENT OR NOT
const t = Engine.createTimerObject();
t.setTimerCallback(function()
{
	if (Content.getComponentUnderMouse() != currentComp)
	{
		MousePanel.set("enabled", true);
		this.stopTimer();
	}
});


//	CHECK AND RETURN HOVERED COMPONENT ID & AREA	--------------------------
inline function whichComp(comps, area)
{
	local x = area[0];
	local y = area[1];

	for (a in comps)
	{
		local minX = a.area[0];
		local maxX = a.area[2] + minX;

		local minY = a.area[1];
		local maxY = a.area[3] + minY;

		if (x >= minX && x <= maxX && y >= minY && y <= maxY)
			return {"id": a.id, "area": a.area};
	}
}
```

# Radial Knob Labels with Rotation

**Source:** [Forum Topic](https://forum.hise.audio/topic/7529)

**Tags:** Scripting, trusted

Panel setPaintRoutine with g.rotate to draw text labels arranged in an arc around a knob. Splits the label array at the midpoint to reverse text alignment for the bottom half, maintaining readability around the full rotation.

```javascript
Content.makeFrontInterface(600, 600);

const labels = ["label1", "label2", "label3", "label4", "label5", "label6", "label7", "label8", "label9", "label10",
                "label11"];

const var Knob1 = Content.getComponent("Knob1");

const var Panel1 = Content.getComponent("Panel1");

Panel1.setPaintRoutine(function(g)
{
	var a = this.getLocalBounds(0);
	var start = -Math.PI / 4.0;
	var arc = 3.0 * Math.PI / 2.0;
	var step = arc / (labels.length - 1);
	var reversePoint = Math.floor(labels.length / 2.0);

	g.rotate(start, [a[2] / 2, a[3] / 2]);

	for (i = 0; i < labels.length; i++)
	{
		g.setColour((this.data.v == i ) ? Colours.red : Colours.white);

		if (i < reversePoint)
		{
