# Radial Labels with Square Aspect Correction

**Source:** [Forum Topic](https://forum.hise.audio/topic/7529)

**Tags:** Scripting, trusted

Improved radial label layout using conformToSquare helper to normalize the panel bounds before rotating. Reverses text alignment at the midpoint and adds indentation offset for better readability of labels like musical scale names.

```javascript
Content.makeFrontInterface(600, 600);

const labels = ["None", "Rast", "Bayati", "Sabba", "Sikah", "Hijaz", "Ajam", "Nahawand", "Hijaz Kar", "Kurd",
                "Nawa Athar"]

      const var Knob1 = Content.getComponent("Knob1");

const var Panel1 = Content.getComponent("Panel1");

Panel1.setPaintRoutine(function(g)
{
	var a = conformToSquare(this.getLocalBounds(0));

	var start = -Math.PI / 4.0;
	var arc = 3.0 * Math.PI / 2.0;
	var step = arc / (labels.length - 1);
	var reversePoint = Math.floor(labels.length / 2.0);

	var someIdentation = 170;

	g.rotate(start, [a[0] + a[2] / 2, a[3] / 2]);

	for (i = 0; i < labels.length; i++)
	{
		g.setColour((this.data.v == i ) ? Colours.red : Colours.white);

		if (i < reversePoint)
		{
			g.drawAlignedText(labels[i], [a[0] - someIdentation, a[1], a[2], a[3]], "right");
			g.rotate(step, [a[0] + a[2] / 2, a[3] / 2]);
			continue;
		}

		if (i == reversePoint)
			g.rotate(Math.PI, [a[0] + a[2] / 2, a[3] / 2]);

		g.drawAlignedText(labels[i], [a[0] + someIdentation, a[1], a[2], a[3]], "left");
		g.rotate(step, [a[0] + a[2] / 2, a[3] / 2]);
	}
});


inline function conformToSquare(a)
{
	a[0] = (a[2] - a[3]) / 2;
	a[2] = a[3];

	return a;
}


inline function onKnob1Control(component, value)
{
	Panel1.data.v = value;
	Panel1.repaint();
};

Knob1.setControlCallback(onKnob1Control);
```

