# FX Panel Live Swap While Dragging

**Source:** [Forum Topic](https://forum.hise.audio/topic/6768)

**Tags:** Scripting, trusted

Content.getAllComponents with setDraggingBounds and setMouseCallback to swap FX panel positions in real-time during a drag operation. Stores the panel order in the parent panel's value for preset persistence, with visual feedback via textColour changes during drag.

```javascript
Content.makeFrontInterface(600, 600);

const MainPanel = Content.getComponent("MainPanel");
const FXPnls = Content.getAllComponents("FXPanel");

//	Hold the x position all the time
for (p in FXPnls)
	p.setDraggingBounds(MainPanel.getLocalBounds(0));

//	I store the order for the fx pnls in the MainPanel value
//	Be sure to set an array to the MainPanel's value if it doesn't
//	already have it stored
if (typeof MainPanel.getValue() != "object")
	MainPanel.setValue([0, 1, 2, 3, 4, 5]);

//	MCB	------------------------------------------------------------
const FXPnlsMCB = function(event)
{
	var h = MainPanel.getHeight();
	var order = MainPanel.getValue();

	var slot = h / FXPnls.length;
	var idx = FXPnls.indexOf(this);

	if (event.clicked || event.drag)
	{
		if (event.clicked)
		{
			for (i = 0; i < FXPnls.length; i++)
				order[i] = Math.round(FXPnls[i].get("y") / slot);

			this.data.startpos = order[idx];

			//	just for the look
			this.set("textColour", Colours.withAlpha(Colours.white, 0.7));
		}

		if (event.drag)
		{
			this.data.pos = Math.round(this.get("y") / slot);

			if (this.data.pos != this.data.startpos)
			{
				var swapidx = order.indexOf(this.data.pos);

				FXPnls[swapidx].set("y", slot * this.data.startpos);

				//	swap places
				order[idx] = this.data.pos;
				order[swapidx] = this.data.startpos;

				//	change start position
				this.data.startpos = this.data.pos;
			}
		}
	}

	if (event.mouseUp)
	{
		this.set("y", slot * this.data.pos);
		this.set("textColour", Colours.withAlpha(Colours.white, 0.2));
		Console.print("release: " + this.data.pos);
	}
};

for (p in FXPnls)
	p.setMouseCallback(FXPnlsMCB);
```

