```javascript
Content.makeFrontInterface(600, 500);

const NUM_ITEMS = 20;

// Viewport1
const Viewport1 = Content.getComponent("Viewport1");

// Panel1
const Panel1 = Content.getComponent("Panel1");
Panel1.data.cols = 4;
Panel1.data.gutter = 10;
