# Master Knob with Storage Panel Recall

**Source:** [Forum Topic](https://forum.hise.audio/topic/3698)

**Tags:** Scripting, trusted

Master knob proportionally scaling child knobs relative to their stored ranges, with a hidden Storage panel for preset persistence. Uses an isMC flag to distinguish between master-driven and direct knob changes, preventing recursive callback loops.

```javascript
Content.makeFrontInterface(500, 400);

const var KNBS = [Content.getComponent("KNB1"),
                  Content.getComponent("KNB2")];

const var Filter = Synth.getEffect("Filter");
// If the callback comes from the MASTER or not
var isMC = false;

// Storage Panel   -----------------
const var STORAGE = Content.getComponent("STORAGE");


// MASTER KNOB -----
inline function onMASTERControl(component, value)
{
	local range = 1.0;  //Master knb

	isMC = true;
	local i;

	for (i = 0; i < KNBS.length; i++)
	{
		local min = KNBS[i].get("min");
		local r = STORAGE.getValue()[i] - min;
		KNBS[i].setValue(r * value - Math.abs(min));
		KNBS[i].changed();
	}

	isMC = false;
};

Content.getComponent("MASTER").setControlCallback(onMASTERControl);


// KNBS Callbacks
inline function onKNBSControl(component, value)
{
	local index = KNBS.indexOf(component);

	// Check if it's the MASTER CB or not
	if (!isMC)
	{
		local temp = STORAGE.getValue();
		temp[index] = value;
		STORAGE.setValue(temp);
	}

	index == 0 ? Filter.setAttribute(Filter.Frequency, value) : "";
};

for (k in KNBS)
	k.setControlCallback(onKNBSControl);

// Get KNBS present values function
function getValues(array)
{
	var result = [];

	for (a in array)
		result.push(a.getValue());

	return result;
}

// Set the KNBS present values at init
STORAGE.setValue(getValues(KNBS));
