{
	//Console.print(ConvolutionReverb1.getCurrentLevel(1));

	reg wetL = ConvolutionReverb1.getCurrentLevel(1);
	reg wetR = ConvolutionReverb1.getCurrentLevel(0);

	knbWetL.setValue(Engine.getDecibelsForGainFactor(wetL));
	knbWetR.setValue(Engine.getDecibelsForGainFactor(wetR));

	reg dryL = Empty1.getCurrentLevel(1);
	reg dryR = Empty1.getCurrentLevel(0);

	knbDryL.setValue(Engine.getDecibelsForGainFactor(dryL) + ConvolutionReverb1.getAttribute(ConvolutionReverb1.DryGain));
