# Radial Multi-Value Pad Controller

**Source:** [Forum Topic](https://forum.hise.audio/topic/2155)

**Tags:** Scripting, trusted

Panel with circular layout storing 5 values at angular positions. Uses setPaintRoutine with trigonometric calculations for spot positioning and setMouseCallback for drag interaction with angle and radius computation.

```javascript
Content.makeFrontInterface(300, 500);
const var areas = [Content.getComponent("area1"),
                   Content.getComponent("area2"),
                   Content.getComponent("area3"),
                   Content.getComponent("area4"),
                   Content.getComponent("area5")];

const var MultiPad = Content.getComponent("MultiPad");

MultiPad.data.value = {};
MultiPad.data.value.length = [];
MultiPad.data.value.values = [1, 1, 1, 1, 1];
MultiPad.data.value.marker = 60;
MultiPad.data.value.angles = [162, 234, 306, 18, 90];
MultiPad.data.value.order = [0, 1, 2, 3, 4];
MultiPad.data.value.angle = 0;
MultiPad.data.value.rad = 1;

MultiPad.setPaintRoutine(function(g)
{
	var v = this.data.value;
	var w = this.getWidth();
	var h = this.getHeight();

	// mask
	var path = Content.createPath();
	path.addArc([0, 0, w, h], 0, Math.PI * 2);

	// bgCircle
	g.setColour(0x55FFFFFF);
	g.fillEllipse([0, 0, w, h]);

	// 5 spots
	g.beginLayer(true);
	g.setColour(0xFFAAAA00);
	g.fillEllipse([v.x0 - 5, v.y0 - 5, 10, 10]);
	g.fillEllipse([v.x1 - 5, v.y1 - 5, 10, 10]);
	g.fillEllipse([v.x2 - 5, v.y2 - 5, 10, 10]);
	g.fillEllipse([v.x3 - 5, v.y3 - 5, 10, 10]);
	g.fillEllipse([v.x4 - 5, v.y4 - 5, 10, 10]);
	g.endLayer();


	// 5 slices    ==================================
	// Bassoon
	g.beginLayer(true);
	g.setColour(0x7700AAFF);
	g.rotate(Math.toRadians(v.angles[v.order[0]]), [w / 2, h / 2]);
	g.fillTriangle([w * 0.135, 0, w * 0.73, h / 2], Math.PI);
	g.setColour(this.get("itemColour"));
	g.setFont("Oxygen", this.get("borderRadius"));
	g.drawAlignedText(Engine.doubleToString(v.values[v.order[0]], 2), [0, 0, w, h / 2 - 60], "centred");
	g.setColour(this.get("textColour"));
	g.setFont("Oxygen", this.get("borderSize"));
	g.drawAlignedText("Bassoon", [0, 0, w, h / 2], "centred");
	g.applyMask(path, [0, 0, w, h], false);
	g.endLayer();

	// Bandoneon
	g.beginLayer(true);
	g.setColour(0x770088AA);
	g.rotate(Math.toRadians(v.angles[v.order[1]]), [w / 2, h / 2]);
	g.fillTriangle([w * 0.135, 0, w * 0.73, h / 2], Math.PI);
	g.setColour(this.get("itemColour"));
	g.setFont("Oxygen", this.get("borderRadius"));
	g.drawAlignedText(Engine.doubleToString(v.values[v.order[1]], 2), [0, 0, w, h / 2 - 60], "centred");
	g.setColour(this.get("textColour"));
	g.setFont("Oxygen", this.get("borderSize"));
	g.drawAlignedText("Bandoneon", [0, 0, w, h / 2], "centred");
	g.applyMask(path, [0, 0, w, h], false);
	g.endLayer();

	// Master
	g.beginLayer(true);
	g.setColour(0x7700DDAA);
	g.rotate(Math.toRadians(v.angles[v.order[2]]), [w / 2, h / 2]);
	g.fillTriangle([w * 0.135, 0, w * 0.73, h / 2], Math.PI);
	g.setColour(this.get("itemColour"));
	g.setFont("Oxygen", this.get("borderRadius"));
	g.drawAlignedText(Engine.doubleToString(v.values[v.order[2]], 2), [0, 0, w, h / 2 - 60], "centred");
	g.setColour(this.get("textColour"));
	g.setFont("Oxygen", this.get("borderSize"));
	g.drawAlignedText("Master", [0, 0, w, h / 2], "centred");
	g.applyMask(path, [0, 0, w, h], false);
	g.endLayer();

	// Violin
	g.beginLayer(true);
	g.setColour(0x7700AAAA);
	g.rotate(Math.toRadians(v.angles[v.order[3]]), [w / 2, h / 2]);
	g.fillTriangle([w * 0.135, 0, w * 0.73, h / 2], Math.PI);
	g.setColour(this.get("itemColour"));
	g.setFont("Oxygen", this.get("borderRadius"));
	g.drawAlignedText(Engine.doubleToString(v.values[v.order[3]], 2), [0, 0, w, h / 2 - 60], "centred");
	g.setColour(this.get("textColour"));
	g.setFont("Oxygen", this.get("borderSize"));
	g.drawAlignedText("Violin", [0, 0, w, h / 2], "centred");
	g.applyMask(path, [0, 0, w, h], false);
	g.endLayer();

	// Clarinet
	g.beginLayer(true);
	g.setColour(0x7700DDAA);
	g.rotate(Math.toRadians(v.angles[v.order[4]]), [w / 2, h / 2]);
	g.fillTriangle([w * 0.135, 0, w * 0.73, h / 2], Math.PI);
	g.setColour(this.get("itemColour"));
	g.setFont("Oxygen", this.get("borderRadius"));
	g.drawAlignedText(Engine.doubleToString(v.values[v.order[4]], 2), [0, 0, w, h / 2 - 60], "centred");
	g.setColour(this.get("textColour"));
	g.setFont("Oxygen", this.get("borderSize"));
	g.drawAlignedText("Clarinet", [0, 0, w, h / 2], "centred");
	g.applyMask(path, [0, 0, w, h], false);
	g.endLayer();

	// Marker
	g.beginLayer(true);
	g.setColour(0x77FFFFFF);
	g.fillEllipse([v.x - v.marker * 0.5, v.y - v.marker * 0.5, v.marker, v.marker]);
	g.applyMask(path, [0, 0, w, h], false);
	g.endLayer();

	this.setValue(v);
});

var area = 0;
var closest = 400;
var tempAngle = 0;
var dropAngle = 0;
var curr = 400;
var slice = 0;

// Mouse Callback  ------------------------------------------
MultiPad.setMouseCallback(function(event)
{
	var anglesTrue = [162, 234, 306, 18, 90];

	var w = this.getWidth();
	var h = this.getHeight();
	var v = this.data.value;

	if(event.clicked || event.drag && !event.shiftDown && !event.altDown)
	{
		v.x = event.x;
		v.y = event.y;

		v.xVal = Math.range(event.x / (w * 0.5) - 1, -1, 1) ;
		v.yVal = Math.range(2 - event.y / (h * 0.5) - 1, -1, 1);

		// Calculate the radius    -----------------------------
		v.rad = Math.sqrt(Math.sqr(v.xVal) + Math.sqr(v.yVal));
		v.rad = Math.range(v.rad, 0, 1);

		// length between marker and areas
		v.x0 = w / 2 + w / 2 * v.rad * Math.cos(Math.PI * 0.4); //Bassoon
		v.y0 = h / 2 + w / 2 * v.rad * Math.sin(Math.PI * 0.4);

		v.x1 = w / 2 + w / 2 * v.rad * Math.cos(Math.PI * 0.8); //Bandoneon
		v.y1 = h / 2 + w / 2 * v.rad * Math.sin(Math.PI * 0.8);

		v.x2 = w / 2 + w / 2 * v.rad * Math.cos(Math.PI * 1.2); //Master
		v.y2 = h / 2 + w / 2 * v.rad * Math.sin(Math.PI * 1.2);

		v.x3 = w / 2 + w / 2 * v.rad * Math.cos(Math.PI * 1.6); //Violin
		v.y3 = h / 2 + w / 2 * v.rad * Math.sin(Math.PI * 1.6);

		v.x4 = w / 2 + w / 2 * v.rad * Math.cos(Math.PI * 2.0); //Clarinet
		v.y4 = h / 2 + w / 2 * v.rad * Math.sin(Math.PI * 2.0);

		v.length[0] = Math.sqrt(Math.sqr(v.x0 - v.x) + Math.sqr(v.y0 - v.y));
		v.length[1] = Math.sqrt(Math.sqr(v.x1 - v.x) + Math.sqr(v.y1 - v.y));
		v.length[2] = Math.sqrt(Math.sqr(v.x2 - v.x) + Math.sqr(v.y2 - v.y));
		v.length[3] = Math.sqrt(Math.sqr(v.x3 - v.x) + Math.sqr(v.y3 - v.y));
		v.length[4] = Math.sqrt(Math.sqr(v.x4 - v.x) + Math.sqr(v.y4 - v.y));

		// Calculate values depended on distance between Marker and the 5 areas
		for(i = 0; i < 5; i++)
		{
			if(v.length[i] < v.marker)
			{
				v.values[i] = 1 - v.length[i] * (1 / (v.marker));
				//areas[v.order[i]].setValue(v.values[i]);
				areas[i].setValue(v.values[v.order[i]]);
			}

			else
			{
				v.values[i] = 0;
				//areas[v.order[i]].setValue(0);
				areas[i].setValue(v.values[v.order[i]]);
			}
		}
	}

	if(event.clicked && event.shiftDown)
	{
		// Calculate closest area from marker (when clicked)
		for(i = 0; i < 5; i++)
		{
			if(v.length[i] < closest)
			{
				closest = v.length[i];
				area = i;
				slice = v.order[area];
				Console.print("area:" + area + " slice:" + slice);
			}
		}

		tempAngle = anglesTrue[v.order[slice]];
		//Console.print("tempAngle:"+tempAngle);

	}

	if(event.shiftDown && event.drag)
	{
		dropAngle = tempAngle + (event.dragX - event.dragY);

		if(dropAngle < 0)
			dropAngle = dropAngle + 360;

		if(dropAngle > 360)
			dropAngle = dropAngle - 360;

		v.angles[v.order[slice]] = dropAngle;
		//Console.print("dropAngle:"+dropAngle);
	}

	if(event.shiftDown && event.mouseUp && dropAngle > 0)
	{
		var dropArea = 9;

		if(dropAngle > 126 && dropAngle < 198)
			dropArea = 0;

		if(dropAngle > 198 && dropAngle < 270)
			dropArea = 1;

		if(dropAngle > 270 && dropAngle < 342)
			dropArea = 2;

		if(dropAngle > 342 || dropAngle < 54)
			dropArea = 3;

		if(dropAngle > 54 && dropAngle < 126)
			dropArea = 4;

		// test
		var temp1 = v.order.indexOf(area);
		var temp2 = v.order.indexOf(dropArea);
		v.order[temp1] = dropArea;
		v.order[temp2] = area;


		for(i = 0; i < 5; i++)
		{
			v.angles[i] = anglesTrue[i];
			this.repaint();
			Console.print("order:" + v.order[i]);
		}

		//Console.print("dropAngle:"+dropAngle);
		//Console.print("dropArea:"+dropArea);
		closest = 400;
		dropAngle = 0;  // reset dropAngle

	}


	// Scale marker size   =========================================
	if(event.altDown && event.drag)
	{
		v.marker = v.marker + (event.dragX - event.dragY) * 0.1;
		v.marker = Math.range(v.marker, 40, 160);
		this.repaint();
	}

	this.setValue(v);
	this.repaint();
	this.changed();

});

//

inline function onMultiPadControl(component, value)
{
	if(isDefined(value))
	{
		component.data.value = value;
		component.repaint();
	}
};

Content.getComponent("MultiPad").setControlCallback(onMultiPadControl);
```

