```javascript
Content.makeFrontInterface(600, 500);

const var XYPadPnl = Content.getComponent("XYPadPnl");

// Add a subobject to the data slot which will be passed
// to setValue()
XYPadPnl.data.value = {};
XYPadPnl.data.value.xVal = 0.5;
XYPadPnl.data.value.yVal = 0.5;
XYPadPnl.data.value.x = XYPadPnl.get("width") / 2;
XYPadPnl.data.value.y = XYPadPnl.get("height") / 2;

XYPadPnl.setPaintRoutine(function(g)
{
	var w = this.getWidth();
	var h = this.getHeight();

	// Just create a reference to this monster of an expression to save typing
	var v = this.data.value;

	g.fillAll(this.get("bgColour"));

	g.setGradientFill([this.get("itemColour"), 0, 0, this.get("itemColour2"), 0, this.getHeight() * 0.5]);
	g.drawRect([0, 0, w, h], 2);
	g.drawLine(0, w, h * 0.25, h * 0.25, this.get("borderSize"));
	g.drawLine(0, w, h * 0.5, h * 0.5, this.get("borderSize"));
	g.drawLine(0, w, h * 0.75, h * 0.75, this.get("borderSize"));
	g.drawLine(0, w, h, h, this.get("borderSize"));
	g.drawLine(w * 0.25, w * 0.25, 0, h, this.get("borderSize"));
	g.drawLine(w * 0.50, w * 0.50, 0, h, this.get("borderSize"));
	g.drawLine(w * 0.75, w * 0.75, 0, h, this.get("borderSize"));
	g.drawLine(w, w, 0, h, this.get("borderSize"));

	g.setColour("0x5500FFFF");
	g.drawLine(v.x + w * 0.04, v.x - w * 0.04, v.y, v.y, 2);
	g.drawLine(v.x, v.x, v.y - h * 0.04, v.y + h * 0.04, 2);
	g.setColour("0x55FFFFFF");
	v.xVal == undefined ? v.xVal = 0 : v.xVal;
	v.yVal == undefined ? v.yVal = 0 : v.yVal;
	g.drawAlignedText("x = " + v.xVal + ", y = " + v.yVal, [0, h - 14, w, 10], "centred");
});


XYPadPnl.setMouseCallback(function(event)
{
	var x = event.mouseDownX;
	var y = event.mouseDownY;
	var v = this.data.value;

	if(event.drag || event.clicked)
	{
		v.x = Math.range(x + event.dragX, 0, this.getWidth());
		v.y = Math.range(y + event.dragY, 0, this.getHeight());

		v.xVal = (Math.floor((v.x) / this.getWidth() * 100) * 0.01);
		v.yVal = 1 - (Math.floor((v.y) / this.getHeight() * 100) * 0.01);

		// This is the magic command: you can call setValue() with
		// JSON objects too, so we just pass the entire object to the
		// internal value which then is subject to the default HISE restoring
		// mechanisms (initalisation, user preset loading, etc).
		// Javascript object referencing will make sure
		// it will always operate on the same object.
		this.setValue(v);

		this.changed();
	}

	if(event.drag || event.clicked)
		InfoLbl.setPosition(v.x, v.y + 20, 80, 30);

});


inline function onXYPadPnlControl(component, value)
{
	// It might get called with undefined at initialisation...
	if(isDefined(value))
	{
		// Store the object back into the data slot. Since we know that
		// this object is already referenced in the data slot it will not
		// reallocate.
		component.data.value = value;
		component.repaint();

		// Be aware that this function call is not realtime safe so if you
		// start controlling your XY-pad with a MIDI message, you might
		// cause drop outs because you're doing UI work on the audio thread
		InfoLbl.set("text", "x = " + value.xVal + "\n" + "y = " + value.yVal);
	}
};

Content.getComponent("XYPadPnl").setControlCallback(onXYPadPnlControl);


// Info Label following the mouse  ...................
const var InfoLbl = Content.getComponent("InfoLbl");
