```javascript
Content.makeFrontInterface(600, 500);
Console.clear();

const var YmemKnb = Content.getComponent("YmemKnb");
const var XmemKnb = Content.getComponent("XmemKnb");


const var pnlMenu = Content.getComponent("pnlMenu");
const var verticalOffset = 50;
const var itemHeight = 200;
const var numRows = 10;
const var numCols = 10;

const var rowSlice = [];

for (i = 0; i < numRows; i++)

	rowSlice.push(pnlMenu.getHeight() / numRows * i);

const var colSlice = [];

for (i = 0; i < numCols; i++)

	colSlice.push(pnlMenu.getWidth() / numCols * i);


pnlMenu.setPaintRoutine(function(g)
{
	g.fillAll(Colours.black);

	g.setColour(Colours.beige); // Sets the current brush to half transparent red

	// horizontal lines
	for (i = 0; i < numRows + 1; i++)

		g.drawLine(0, this.getWidth(), i * this.getHeight() / numRows, i * this.getHeight() / numRows, 0.5);

	// vertical lines
	for (i = 0; i < numCols + 1; i++)

		g.drawLine(i * this.getWidth() / numCols, i * this.getWidth() / numCols, 0, this.getHeight(), 0.5);

	// Draw the square
	g.fillRect([XmemKnb.getValue(),
	            YmemKnb.getValue(),
	            this.getWidth() / numCols,
	            this.getHeight() / numRows]);
});

// Menu Panel Mouse CB
pnlMenu.setMouseCallback(function(event)
{
	if (event.hover)
	{

		mousePos(event.y, event.x);

		pnlMenu.set("tooltip",
		            "Row " + (rowSlice.indexOf(pnlMenu.data.Y) + 1) +
		            " - Col " + (colSlice.indexOf(pnlMenu.data.X) + 1));
	}

	if (event.clicked)
	{
		mousePos(event.y, event.x);

		memorisePnlBtn();

		pnlMenu.repaint();

	}
});


inline function mousePos(Y, X)
{

	// determine the position of the square from the click event
	pnlMenu.data.Y = rowSlice[Math.floor(Y / (this.getHeight() / numRows))];
	pnlMenu.data.X = colSlice[Math.floor(X / (this.getWidth() / numCols))];
};


inline function memorisePnlBtn()
{

	YmemKnb.setValue(pnlMenu.data.Y);
	XmemKnb.setValue(pnlMenu.data.X);
};


inline function onKnobControl(component, value)
{
