# Rounded Tab Button LAF with Panel Toggle

**Source:** [Forum Topic](https://forum.hise.audio/topic/8450)

**Tags:** General Questions, trusted

drawToggleButton LAF using Content.createPath with quadraticTo to draw rounded tab shapes. Active and inactive states use different corner rounding. Paired with a callback that shows/hides corresponding panels based on button index.

```javascript
Content.makeFrontInterface(600, 600);

const var btns = [Content.getComponent("Button1"),
                  Content.getComponent("Button2")];

const var pnls = [Content.getComponent("Panel1"),
                  Content.getComponent("Panel2")];

const var R = 6;
const var TWO_R = R * 2;

const var tabLAF = Content.createLocalLookAndFeel();

tabLAF.registerFunction("drawToggleButton", function(g, obj)
{
	var a = obj.area;
	var p = Content.createPath();

	p.startNewSubPath(TWO_R, 0);
	p.lineTo(a[2] - TWO_R, 0);
	p.quadraticTo(a[2] - R, 0, a[2] - R, R);

	if (obj.value)
	{
		p.lineTo(a[2] - R, a[3] - R);
		p.quadraticTo(a[2] - R, a[3], a[2], a[3]);
		p.lineTo(0, a[3]);
		p.quadraticTo(R, a[3], R, a[3] - R);
	}

	else
	{
		p.lineTo(a[2] - R, a[3]);
		p.lineTo(a[2], a[3]);
		p.lineTo(0, a[3]);
		p.lineTo(R, a[3]);
	}

	p.lineTo(R, R);
	p.quadraticTo(R, 0, TWO_R, 0);

	g.setColour(obj.value ? obj.bgColour : 0xFF808080);
	g.fillPath(p, a);

	g.setColour(obj.value ? obj.itemColour2 : obj.textColour);
	g.drawAlignedText(obj.text, obj.area, "centred");
});


for (b in btns)
{
	b.setLocalLookAndFeel(tabLAF);
	b.setControlCallback(onbtnsControl);
}


inline function onbtnsControl(component, value)
{
	for (p in pnls)
	{
		if (pnls.indexOf(p) == btns.indexOf(component))
			p.showControl(value);
	}
};
```

