# Animated Knob Border on Hover

**Source:** [Forum Topic](https://forum.hise.audio/topic/7977)

**Tags:** General Questions, trusted

drawRotarySlider LAF with Engine.createTimerObject to animate a dot tracing the knob border on hover. Uses a state machine (xinc/yinc/xdec/ydec) with reg variables for persistent animation state across paint calls.

```javascript
Content.makeFrontInterface(600, 600);

const var Knbs = [Content.getComponent("Knb"),
                  Content.getComponent("Knb1"),
                  Content.getComponent("Knb2"),
                  Content.getComponent("Knb3")];


const KnbLaf = Content.createLocalLookAndFeel();

KnbLaf.registerFunction("drawRotarySlider", function(g, obj)
{
	//Console.print(trace(obj));
	g.fillAll(obj.bgColour);

	reg a = obj.area;
	reg speed = 10;
	reg ani = !isDefined(ani) ? 0 : ani;
	reg comp = Content.getComponent(obj.id);
	reg t = !isDefined(t) ? Engine.createTimerObject() : t;
	reg inc = !isDefined(inc) ? true : inc;
	reg state = !isDefined(state) ? "xinc" : state;
	reg xy = !isDefined(xy) ? [0, 0, 0, 0] : xy;

	if (obj.hover)
	{
		t.setTimerCallback(function()
		{
			switch (state)
			{
			case "xinc":
				ani = ani + speed;
				xy = [ani, 0];

				if (ani + speed > a[2])
				{
					state = "yinc";
					ani = 0;
					xy = [a[2], ani];
				}

				break;

			case "yinc":
				ani = ani + speed;
				xy = [a[2], ani];

				if ((ani + speed) % a[3] == 0)
				{
					state = "xdec";
					ani = a[2];
					xy = [ani, a[3]];
				}

				break;

			case "xdec":
				ani = ani - speed;
				xy = [ani, a[3]];

				if (ani - speed < 0)
				{
					state = "ydec";
					ani = a[3];
					xy = [0, ani];
				}

				break;

			case "ydec":
				ani = ani - speed;
				xy = [0, ani];

				if (ani - speed < 0)
				{
					state = "xinc";
					ani = 0;
					xy = [ani, 0];
				}

				break;
			}

			comp.sendRepaintMessage();
		});

		t.startTimer(30);
		g.setColour(obj.itemColour1);
		g.fillEllipse([xy[0] - 6, xy[1] - 6, 12, 12]);
	}

	if (!obj.hover)
	{
		ani = undefined;
		inc = true;
		t.stopTimer();
	}
});


for (k in Knbs)
	k.setLocalLookAndFeel(KnbLaf);
```

# Rotating Blur Animation on Knob Hover

**Source:** [Forum Topic](https://forum.hise.audio/topic/7977)

**Tags:** General Questions, trusted

drawRotarySlider LAF with Engine.createTimerObject and g.rotate for a sweeping light animation on hover. Uses beginLayer/gaussianBlur/endLayer for a glow effect, with getMilliSecondsSinceCounterReset for frame-independent timing.

```javascript
Content.makeFrontInterface(600, 600);

const var Knbs = [Content.getComponent("Knb"),
                  Content.getComponent("Knb1"),
                  Content.getComponent("Knb2"),
                  Content.getComponent("Knb3")];

const var Speed = Content.getComponent("Speed");
const var Degrees = Content.getComponent("Degrees");
const var Blur = Content.getComponent("Blur");
const var Width = Content.getComponent("Width");


const KnbLaf = Content.createLocalLookAndFeel();

KnbLaf.registerFunction("drawRotarySlider", function(g, obj)
{
	reg a = obj.area;
	reg comp = Content.getComponent(obj.id);
	reg t = !isDefined(t) ? Engine.createTimerObject() : t;
	reg count = !isDefined(count) ? 0 : count;
	reg done = !isDefined(done) ? false : done;
	var w = Width.getValue();

	if (obj.hover)
	{
		t.setTimerCallback(function()
		{
			count = parseInt(t.getMilliSecondsSinceCounterReset() / (12 - Speed.getValue()));

			if (count > Degrees.getValue())
			{
				done = true;
				count = 0;
				t.stopTimer();
			}

			comp.sendRepaintMessage();
		});

		if (!t.isTimerRunning() && !done)
			t.startTimer(30);
	}

	if (!obj.hover)
	{
		count = 0;
		done = undefined;
		t.stopTimer();
	}

	g.beginLayer(false);

	//	Animation
	if (count > 0)
	{
		g.rotate(Math.toRadians(count), [a[2] / 2, a[3] / 2]);
		g.setColour(Colours.white);
		g.fillRoundedRectangle([a[2] / 2 - w, -a[3], w * 2, a[3] * 3], 2);
	}

	g.rotate(Math.toRadians(-count), [a[2] / 2, a[3] / 2]);
	g.gaussianBlur(Blur.getValue());
	g.endLayer();

	//	Rectangle
	g.setColour(obj.bgColour);
	g.fillRoundedRectangle([2, 2, a[2] - 4, a[3] - 4], 6);

	//	Object text
	g.setFont("default", a[3] / 3);
	g.setColour(Colours.withAlpha(obj.textColour, 0.3));
	g.drawAlignedText(obj.text, a, "centred");

	//	Handle
	g.setColour(obj.itemColour2);
	g.fillRoundedRectangle([(a[2] - 4)*obj.valueNormalized, 6, 5, a[3] - 12], 2);

	//	Value
	g.setFont("default", 13);
	g.setColour(Colours.withAlpha(obj.textColour, 0.7));
	g.drawAlignedText(obj.valueAsText, [0, 6, a[2], a[3] - 12], "centredTop");
});


for (k in Knbs)
	k.setLocalLookAndFeel(KnbLaf);
