# XML Parameter Duplicate Detector

**Source:** [Forum Topic](https://forum.hise.audio/topic/7588)

**Tags:** General Questions, trusted

FileSystem.browse to load a Desktop.xml file, then loadAsString and split to parse widget definitions. Scans for duplicate pluginParameterName values across ScriptButton and ScriptSlider elements and reports the offending widget IDs.

```javascript
Content.makeFrontInterface(480, 600);

const var SelectedFilePath = Content.getComponent("SelectedFilePath");
SelectedFilePath.set("text", "...");
const var Results = Content.getComponent("Results");
Results.set("text", "...");

reg targetFile;
reg jsonFile;
reg fileAsString;
reg fileAsArray;
reg tempParam;
reg tempID;
const paramArray = [];

inline function onSelectXMLFileControl(component, value)
{
	if(value) //momentary  button-so only exute on press down
	{
		// open a file browser to let the user select an xmlfile
		FileSystem.browse(".", false, "*.xml", function(result)
		{
			//got a file so...
			targetFile = result;
			SelectedFilePath.set("text", result.toString(File.FullPath)); //show the path
		});
	};
};

Content.getComponent("SelectXMLFile").setControlCallback(onSelectXMLFileControl);


inline function onRunTestControl(component, value)
{
	if(value)
	{
		//the user wishes to execute the test....

		//reset the results display....
		Results.set("text", "....");
		//reset the array weuse to test for duplicates
		paramArray.clear();
		//jsonFile = targetFile.loadFromXmlFile(); <--- oh how I wish this worked....
		// get teh file into a string...and split it based upon "="
		fileAsString = targetFile.loadAsString();
		fileAsArray = fileAsString.split("=");
		// now we shoud have an ugly array with params name and param values in adjacent array slots

		//Console.print(trace(fileAsArray));

		for (i = 0; i < fileAsArray.length; i++)
		{
			// move thru the array looking for the type of widget we care about...

			if(fileAsArray[i].contains("ScriptButton") || fileAsArray[i].contains("ScriptSlider"))
			{
				//Ok we found one.. so look in its "block" tosee if it uses a plugin param...

				reg j = i;

				while(!fileAsArray[j].contains("/>"))
				{
					// search this block for the plugin param name...
					if (fileAsArray[j].contains("pluginParameterName"))
					{
						// found it.,so the next array elemtn will include its name
						tempParam = fileAsArray[j + 1];
						// clean up
						tempParam = tempParam.substring(1, tempParam.lastIndexOf("\""));

						// check for duplicates...
						if (paramArray.indexOf(tempParam) != -1)
						{
							// dupe found...
							Results.set("text", Results.get("text") + "\n" + "ERROR--------DUPLICATE---:" + tempParam);
						}

						else
							paramArray.push(tempParam);

						// this is a param user - search the same block for its ID
						reg k = i;

						while(!fileAsArray[k].contains("/>"))
						{
							if (fileAsArray[k].contains(" id"))
							{
								tempID = fileAsArray[k + 1].substring(1, fileAsArray[k + 1].lastIndexOf("\""));
								break;  //got it so leave this search
							};

							k++;
						};

						// print the result..
						//Console.print("PARAM:" + tempParam + " -used by: " + tempID);
						Results.set("text", Results.get("text") + "\n" + "PARAM:" + tempParam + " - used by:" + tempID);

						break;  // got it so leave this search

					};

					j++;
				}

			}

		}
	};

};

Content.getComponent("RunTest").setControlCallback(onRunTestControl);
```

# Reorderable Effect Rack Panels

**Source:** [Forum Topic](https://forum.hise.audio/topic/7044)

**Tags:** General Questions, trusted, solved

Draggable effect panel reordering using a state array stored in a container panel value. Prev/Next buttons swap adjacent panel positions by manipulating the state array and repositioning panels via set("x"). State is preset-saveable through the container panel.

```javascript
Content.makeFrontInterface(1000, 200);

const numRacks = 5;
const panelWidth = 190;
const panelHeight = 140;
const arry_EffectPanel = [];
const arry_PrevBtn = [];
const arry_NextBtn = [];

const var stateObj = {state: [0, 1, 2, 3, 4]};

const var Container = Content.getComponent("Container");
inline function onContainerControl(component, value)
{

	if (typeof(component.getValue()) == "object")
		panelOrderHandler();

	else
	{
		component.setValue(stateObj);
		panelOrderHandler();
	}

};

Content.getComponent("Container").setControlCallback(onContainerControl);


for (i = 0; i < numRacks; i++)
{
	arry_EffectPanel.push(Content.getComponent("EffectPanel" + i));

	arry_PrevBtn.push(Content.getComponent("PrevBtn" + i));
	arry_PrevBtn[i].setControlCallback(onarry_PrevBtnControl);

	arry_NextBtn.push(Content.getComponent("NextBtn" + i));
	arry_NextBtn[i].setControlCallback(onarry_NextBtnControl);
}


inline function panelOrderHandler()
{
	local panelVal = Container.getValue().state;

	for (i = 0; i < numRacks; i++)
	{
		arry_EffectPanel[panelVal[i]].set("x", panelWidth * i);
		arry_PrevBtn[i].set("visible", true);
		arry_NextBtn[i].set("visible", true);
	}

	arry_PrevBtn[panelVal[0]].set("visible", false);
	arry_NextBtn[panelVal[4]].set("visible", false);
}


inline function onarry_PrevBtnControl(component, value)
{
	if (value)
	{
		local idx = arry_PrevBtn.indexOf(component);
		local containerVal = Container.getValue().state;
		local getPos = arry_EffectPanel[idx].get("x") / panelWidth;
		local swappedPanel = containerVal[getPos - 1];

		containerVal[getPos] = swappedPanel;
		containerVal[getPos - 1] = idx;

		local Data = {state: containerVal};

		Container.setValue(Data);
		Container.changed();
	}
}


inline function onarry_NextBtnControl(component, value)
{
	if (value)
	{
		local idx = arry_NextBtn.indexOf(component);
		local containerVal = Container.getValue().state;
		local getPos = arry_EffectPanel[idx].get("x") / panelWidth;
		local swappedPanel = containerVal[getPos + 1];

		containerVal[getPos] = swappedPanel;
		containerVal[getPos + 1] = idx;

		local Data = {state: containerVal};

		Container.setValue(Data);
		Container.changed();
	}
}
```

# Sequenced Timer for Chained Parameter Updates

**Source:** [Forum Topic](https://forum.hise.audio/topic/7377)

**Tags:** General Questions, trusted

Panel timer with a state counter to chain three groups of effect parameter updates with controlled delays. Uses ParaEQ.BandOffset for band-indexed attribute access and prevents re-entry with a data.isRunning flag.

```javascript
Content.makeFrontInterface(300, 200);

const var ParaEQ = Synth.getEffect("ParaEQ");
const var SimpleGainer = Synth.getEffect("SimpleGainer");
const var Reverberate = Synth.getEffect("Reverberate");

const var Knob1TimerPnl = Content.getComponent("Knob1TimerPnl");

reg STATE = 0;
Knob1TimerPnl.setTimerCallback(function()
{
	if (STATE == 0)
	{
		functTwo();
		STATE = 1;
		this.startTimer(50);
	}

	else
	{
		functThree();
		STATE = 0;
		Knob1TimerPnl.data.isRunning = undefined;
		this.stopTimer();
	}
});

const var Knob1 = Content.getComponent("Knob1");

inline function onKnob1Control(component, value)
{
	if (isDefined(Knob1TimerPnl.data.isRunning))
		return;

	else
	{
		functOne();
		Knob1TimerPnl.startTimer(30);
		Knob1TimerPnl.data.isRunning = true;
	}

	/*
	1. Firstly run functOne()
	2. Then wait for 30 ms and run functTwo()
	3. Then wait for 50 ms and run functThree()
	*/
};

Content.getComponent("Knob1").setControlCallback(onKnob1Control);


inline function functOne()
{
	local index_One_Gain = ParaEQ.BandOffset * 1 + ParaEQ.Gain;
	local index_Three_Gain = ParaEQ.BandOffset * 3 + ParaEQ.Gain;

	ParaEQ.setAttribute(index_One_Gain, 13.6 * Knob1.getValue());
	ParaEQ.setAttribute(index_Three_Gain, -10.9 * Knob1.getValue());
	Reverberate.setAttribute(Reverberate.RoomSize, 0.95 - 0.2 * Knob1.getValue());

	Console.print("function 1");
}


inline function functTwo()
{
	local index_One_Freq = ParaEQ.BandOffset * 1 + ParaEQ.Freq;
	local index_Three_Freq = ParaEQ.BandOffset * 3 + ParaEQ.Freq;

	ParaEQ.setAttribute(index_One_Freq, 100 + 1200 * Knob1.getValue());
	ParaEQ.setAttribute(index_Three_Freq, 500 - 400 * Knob1.getValue());
	SimpleGainer.setAttribute(SimpleGainer.Width, 100 + 50 * Knob1.getValue());
	Reverberate.setAttribute(Reverberate.Damping, 1.0 - 0.5 * Knob1.getValue());

	Console.print("function 2");
}


inline function functThree()
{
	SimpleGainer.setAttribute(SimpleGainer.Gain, 0 + 2.3 * Knob1.getValue());

	local index_One_Q = ParaEQ.BandOffset * 1 + ParaEQ.Q;
	local index_Three_Q = ParaEQ.BandOffset * 3 + ParaEQ.Q;

	ParaEQ.setAttribute(index_One_Q, 1.0 - 0.34 * Knob1.getValue());
	ParaEQ.setAttribute(index_Three_Q, 1 + 2.5 * Knob1.getValue());

	Console.print("function 3");
}
```

