ScriptedViewport.setTableMode, setTableColumns, setTableRowData, and setTableCallback for a data table with text cells and action buttons. Custom drawTableCell and drawToggleButton LAF functions style the table rows and button columns.

```javascript
Content.makeFrontInterface(600, 600);

const var Viewport1 = Content.getComponent("Viewport1");
const var ViewportLAF = Content.createLocalLookAndFeel();

ViewportLAF.registerFunction("drawTableCell", function(g, obj)
{
	var a = obj.area;
	g.setColour(Colours.white);
	g.drawAlignedText(obj.text, a, "left");
});

ViewportLAF.registerFunction("drawToggleButton", function(g, obj)
{
	var a = obj.area;
	g.setColour(Colours.grey);

	if (obj.over)
		g.setColour(Colours.darkgrey);

	g.fillRect(a);
});

Viewport1.setLocalLookAndFeel(ViewportLAF);

Viewport1.setTableMode(
{
