"Type": "Text",
	"Width": 380
},
{
"ID": "SecondID",
"Type": "Button",
"Text": "OK",
"Toggle": false,
	"Width": 30
}
                          ]);

Viewport1.setTableRowData([
{ "FirstID": "Some Text", "SecondID": false },
{ "FirstID": "Some other Text", "SecondID": false }
                          ]);

inline function onTableCallback(obj)
{
	if (obj.Type == "Click")
		Console.print("Clicked on text");

